#define RINFS_READAHEAD_MAX_PAGES 32u
#define RINFS_READAHEAD_MIN_SEQUENTIAL_HITS 2u
#define RINFS_READ_PATTERN_FORWARD 1u
#define RINFS_READ_PATTERN_BACKWARD 2u
#define RINFS_READ_PATTERN_RANDOM 3u

