#define rinfs_debug(s) printf("%s", s)
#define rinfs_debug_hex(v) printf("0x%08X", v)

/* Simulated disk I/O for testing */
static FILE* g_disk_file = NULL;
static int g_host_write_fail_after = -1;
static int g_host_flush_fail_after = -1;
static int platform_ata_read(int drive, uint32_t lba, uint32_t count, void* buf) {
    (void)drive;
    if (!g_disk_file) return -1;
    fseek(g_disk_file, lba * 512, SEEK_SET);
    return fread(buf, 512, count, g_disk_file) == count ? 0 : -1;
}
static int platform_ata_write(int drive, uint32_t lba, uint32_t count, const void* buf) {
    (void)drive;
    if (!g_disk_file) return -1;
    if (g_host_write_fail_after == 0) return -1;
    if (g_host_write_fail_after > 0) g_host_write_fail_after--;
    fseek(g_disk_file, lba * 512, SEEK_SET);
    return fwrite(buf, 512, count, g_disk_file) == count ? 0 : -1;
}
static int platform_ata_flush(int drive) {
    (void)drive;
    if (!g_disk_file) return -1;
    if (g_host_flush_fail_after == 0) return -1;
    if (g_host_flush_fail_after > 0) g_host_flush_fail_after--;
    return fflush(g_disk_file) == 0 ? 0 : -1;
}

int rinfs_host_open_disk(const char* path) {
    if (!path || g_disk_file) return -1;
    g_disk_file = fopen(path, "r+b");
    return g_disk_file ? 0 : -1;
}

void rinfs_host_close_disk(void) {
    if (!g_disk_file) return;
    fflush(g_disk_file);
    fclose(g_disk_file);
    g_disk_file = NULL;
}

void rinfs_host_fail_writes_after(int successful_writes) {
    g_host_write_fail_after = successful_writes;
}

void rinfs_host_fail_flushes_after(int successful_flushes) {
    g_host_flush_fail_after = successful_flushes;
}
#endif

#define RINFS_SHARED_HEAP_MAGIC UINT64_C(0x52494e4653484541)
#define RINFS_SHARED_HEAP_ALIGNMENT 16u
#define RINFS_SHARED_HEAP_REAP_PENDING_CONTENT_LEASE 1u
#define RINFS_SHARED_HEAP_REAP_PENDING_DELETE_PATH 2u
#define RINFS_SHARED_HEAP_REAP_PENDING_LEASE_ALLOCATION 3u
#define RINFS_SHARED_HEAP_REAP_PENDING_DELETE_PATH_ALLOCATION 4u

typedef struct {
    uint64_t magic;
    /* Mount validation bounds the shared arena below 4 GiB. Keep
     * split/coalesce publication atomic on IA-32. */
    uint32_t total_bytes;
    uint32_t is_free;
    uint32_t reserved;
    uint32_t owner_token;
    uint32_t allocation_kind;
} RinFS_SharedHeapBlock;

#define RINFS_INODE_TABLE_RECOVERY_IDLE 0u
#define RINFS_INODE_TABLE_RECOVERY_READY 1u

typedef struct {
    volatile uint32_t state;
    uint32_t bytes;
    uint64_t block;
    uint32_t checksum;
    uint32_t owner_row;
    uint32_t owner_lock_generation;
    uint64_t owner_cookie;
    uint32_t header_checksum;
    uint8_t data[RINFS_PAGE_CACHE_PAGE_SIZE];
} RinFS_InodeTableRecoveryLog;

#define RINFS_ALLOCATOR_RECOVERY_IDLE 0u
#define RINFS_ALLOCATOR_RECOVERY_READY 1u
#define RINFS_ALLOCATOR_RECOVERY_BLOCK_ALLOC_ROLLBACK 1u
#define RINFS_ALLOCATOR_RECOVERY_BLOCK_FREE_ROLLBACK 2u
#define RINFS_ALLOCATOR_RECOVERY_INODE_ALLOC_ROLLBACK 3u
#define RINFS_ALLOCATOR_RECOVERY_INODE_FREE 4u

typedef struct {
    volatile uint32_t state;
    uint32_t operation;
    uint32_t owner_row;
    uint64_t target;
    uint32_t target_generation;
    uint32_t owner_lock_generation;
    uint64_t owner_cookie;
    uint32_t checksum;
} RinFS_AllocatorRecoveryLog;

#define RINFS_SHARED_LOCK_OWNER_TAG UINT32_C(0x80000000)
#define RINFS_SHARED_LOCK_OWNER_ROW_MASK UINT32_C(0x0000003f)
#define RINFS_SHARED_LOCK_OWNER_GENERATION_SHIFT 6u
#define RINFS_SHARED_LOCK_OWNER_GENERATION_MASK \
    RINFS_SHARED_OWNER_LOCK_GENERATION_MAX
#define RINFS_CONTENT_LEASE_CLOSING_FORK 2u
#define RINFS_CONTENT_LEASE_CLOSING_EXEC 3u

/* Keep RinFS_Mount's public layout stable. The existing readonly integer is
 * a nonzero fence, so use its otherwise-unused bits to remember which
 * transient recovery failure may be retried without losing sticky fences. */
#define RINFS_READONLY_STICKY UINT32_C(0x00000001)
#define RINFS_READONLY_RECOVERY_BLOCK_ALLOC UINT32_C(0x00000002)
#define RINFS_READONLY_RECOVERY_INODE_ALLOC UINT32_C(0x00000004)
#define RINFS_READONLY_RECOVERY_INODE_TABLE UINT32_C(0x00000008)
#define RINFS_READONLY_RECOVERY_SUPERBLOCK UINT32_C(0x00000010)
#define RINFS_READONLY_RECOVERY_NAMESPACE_JOURNAL UINT32_C(0x00000020)
#define RINFS_READONLY_RECOVERY_RESTORE_SYNC UINT32_C(0x00000040)
#define RINFS_READONLY_RECOVERY_RESTORE_CACHE UINT32_C(0x00000080)
#define RINFS_READONLY_RECOVERY_RESTORE_MASK \
    (RINFS_READONLY_RECOVERY_RESTORE_SYNC | \
     RINFS_READONLY_RECOVERY_RESTORE_CACHE)

static uint32_t rinfs_mount_readonly_state(const RinFS_Mount* mount) {
    if (!mount) return RINFS_READONLY_STICKY;
    return (uint32_t)__atomic_load_n(&mount->readonly, __ATOMIC_ACQUIRE);
}

static void rinfs_mount_force_readonly(RinFS_Mount* mount) {
    if (!mount) return;
    (void)__atomic_fetch_or(&mount->readonly,
                            (int)RINFS_READONLY_STICKY,
                            __ATOMIC_ACQ_REL);
}

static int rinfs_mount_sticky_readonly(const RinFS_Mount* mount) {
    return !mount || (rinfs_mount_readonly_state(mount) &
                      RINFS_READONLY_STICKY) != 0u ||
           (mount->mount_flags & RINFS_MNT_RDONLY) != 0u;
}

static void rinfs_mount_recovery_fence(RinFS_Mount* mount, uint32_t reason,
                                       int error) {
    if (!mount) return;
    if ((error == RINFS_ERR_IO || error == RINFS_ERR_NOMEM ||
         (error == RINFS_ERR_BUSY &&
          reason == RINFS_READONLY_RECOVERY_RESTORE_CACHE)) &&
        !rinfs_mount_sticky_readonly(mount)) {
        (void)__atomic_fetch_or(&mount->readonly, (int)reason,
                                __ATOMIC_ACQ_REL);
        return;
    }
    rinfs_mount_force_readonly(mount);
}

static void rinfs_mount_recovery_clear(RinFS_Mount* mount, uint32_t reason) {
    if (!mount) return;
    (void)__atomic_fetch_and(&mount->readonly, ~(int)reason,
                             __ATOMIC_ACQ_REL);
}

static int rinfs_mount_recovery_only(const RinFS_Mount* mount) {
    uint32_t state = rinfs_mount_readonly_state(mount);
    return mount && state != 0u &&
           (state & RINFS_READONLY_STICKY) == 0u &&
           (mount->mount_flags & RINFS_MNT_RDONLY) == 0u;
}

static int rinfs_inode_table_retry_pending(RinFS_Mount* mount);
static int rinfs_mount_prepare_write(RinFS_Mount* mount);
static int rinfs_namespace_journal_retry_pending(RinFS_Mount* mount);
static int rinfs_block_write_unprepared(RinFS_Mount* mount, uint64_t block,
                                        const void* buf);
static int rinfs_superblock_lock(RinFS_Mount* mount);
static int rinfs_superblock_unlock_status(RinFS_Mount* mount,
                                           int operation_error);

static uint32_t rinfs_allocator_recovery_fence(int inode_bitmap) {
    return inode_bitmap ? RINFS_READONLY_RECOVERY_INODE_ALLOC
                        : RINFS_READONLY_RECOVERY_BLOCK_ALLOC;
}

static int rinfs_shared_owner_query_row(RinFS_Mount* mount,
                                        uint32_t* row_out);
static int rinfs_shared_owner_ledger_valid(const RinFS_Mount* mount);
static int rinfs_journal_recover(RinFS_Mount* mount);
static int rinfs_shared_owner_reap_locked(RinFS_Mount* mount);
static int rinfs_shared_heap_reap_detached_pending_locked(
    RinFS_Mount* mount);
static int rinfs_delete_on_close_disk_marker_matches(
    RinFS_Mount* mount, uint64_t parent_ino, uint32_t parent_generation,
    uint32_t directory, uint64_t target_ino, uint32_t target_generation,
    const char* name, int* matches_out);
static int disk_flush(RinFS_Mount* mount);
static int disk_write_internal(RinFS_Mount* mount, uint64_t sector,
                               uint32_t count, const void* buf,
                               int recovery_write);
static int rinfs_inode_is_cleared(const RinFS_Inode* inode);
static uint64_t block_to_sector(RinFS_Mount* mount, uint64_t block);
static int rinfs_recovery_block_write(RinFS_Mount* mount, uint64_t block,
                                      const void* data);

static void rinfs_shared_lock_fence(RinFS_Mount* mount) {
    if (!mount) return;
    rinfs_mount_force_readonly(mount);
    mount->content_lease_closing = UINT32_MAX;
}

static uint32_t rinfs_shared_lock_token(RinFS_Mount* mount) {
    uint32_t row = 0u;
    uint32_t generation_tag;
    if (!mount || !mount->shared_mapping_base ||
        mount->shared_mount_ready == 0u)
        return 1u; /* mount construction predates cross-process exposure */
    if (rinfs_shared_owner_query_row(mount, &row) != RINFS_OK || row == 0u ||
        row > RINFS_SHARED_OWNER_CAPACITY ||
        !rinfs_shared_owner_ledger_valid(mount)) {
        rinfs_shared_lock_fence(mount);
        return 0u;
    }
    if (__atomic_load_n(
            &mount->shared_owner_ledger->owners[row - 1u].state,
            __ATOMIC_ACQUIRE) != RINFS_SHARED_OWNER_ACTIVE ||
        mount->shared_owner_ledger->owners[row - 1u].owner_cookie == 0u) {
        rinfs_shared_lock_fence(mount);
        return 0u;
    }
    generation_tag = mount->shared_owner_ledger->owners[row - 1u]
                         .lock_generation;
    if (generation_tag == 0u ||
        generation_tag > RINFS_SHARED_LOCK_OWNER_GENERATION_MASK) {
        rinfs_shared_lock_fence(mount);
        return 0u;
    }
    return RINFS_SHARED_LOCK_OWNER_TAG |
           (generation_tag << RINFS_SHARED_LOCK_OWNER_GENERATION_SHIFT) |
           row;
}

static int rinfs_shared_lock_owner_dead(RinFS_Mount* mount,
                                        uint32_t lock_state) {
    uint32_t row;
    uint32_t state;
    if (!mount || (lock_state & RINFS_SHARED_LOCK_OWNER_TAG) == 0u ||
        !rinfs_shared_owner_ledger_valid(mount))
        return -1;
    row = lock_state & RINFS_SHARED_LOCK_OWNER_ROW_MASK;
    if (row == 0u || row > RINFS_SHARED_OWNER_CAPACITY) return -1;
    {
        uint32_t lock_generation =
            (lock_state >> RINFS_SHARED_LOCK_OWNER_GENERATION_SHIFT) &
            RINFS_SHARED_LOCK_OWNER_GENERATION_MASK;
        if (lock_generation == 0u) return -1;
    }
    state = __atomic_load_n(
        &mount->shared_owner_ledger->owners[row - 1u].state,
        __ATOMIC_ACQUIRE);
    if (state == RINFS_SHARED_OWNER_DEAD ||
        state == RINFS_SHARED_OWNER_REAPED)
        return 1;
    if (state != RINFS_SHARED_OWNER_ACTIVE) return -1;
    uint32_t lock_generation =
        (lock_state >> RINFS_SHARED_LOCK_OWNER_GENERATION_SHIFT) &
        RINFS_SHARED_LOCK_OWNER_GENERATION_MASK;
    uint32_t live_generation =
        mount->shared_owner_ledger->owners[row - 1u].lock_generation;
    if (live_generation == 0u ||
        live_generation > RINFS_SHARED_LOCK_OWNER_GENERATION_MASK)
        return -1;
    return lock_generation != live_generation;
}

static int rinfs_recovery_log_owner_token(RinFS_Mount* mount,
                                           uint32_t row,
                                           uint32_t lock_generation,
                                           uint64_t owner_cookie,
                                           uint32_t* token_out) {
    uint32_t current_token;
    uint32_t current_row = 0u;
    uint32_t log_token;
    uint32_t owner_state;
    uint32_t owner_dead;
    if (!mount || !token_out || row == 0u ||
        row > RINFS_SHARED_OWNER_CAPACITY || lock_generation == 0u ||
        lock_generation > RINFS_SHARED_LOCK_OWNER_GENERATION_MASK ||
        owner_cookie == 0u || !rinfs_shared_owner_ledger_valid(mount) ||
        mount->shared_owner_ledger->owners[row - 1u].owner_cookie !=
            owner_cookie)
        return RINFS_ERR_CORRUPT;
    log_token = RINFS_SHARED_LOCK_OWNER_TAG |
                (lock_generation <<
                 RINFS_SHARED_LOCK_OWNER_GENERATION_SHIFT) | row;
    owner_state = __atomic_load_n(
        &mount->shared_owner_ledger->owners[row - 1u].state,
        __ATOMIC_ACQUIRE);
    owner_dead = (uint32_t)rinfs_shared_lock_owner_dead(mount, log_token);
    if ((owner_state == RINFS_SHARED_OWNER_ACTIVE && owner_dead != 0u) ||
        ((owner_state == RINFS_SHARED_OWNER_DEAD ||
          owner_state == RINFS_SHARED_OWNER_REAPED) && owner_dead != 1u) ||
        (owner_state != RINFS_SHARED_OWNER_ACTIVE &&
         owner_state != RINFS_SHARED_OWNER_DEAD &&
         owner_state != RINFS_SHARED_OWNER_REAPED))
        return RINFS_ERR_CORRUPT;
    current_token = rinfs_shared_lock_token(mount);
    if (current_token == 0u) return RINFS_ERR_CORRUPT;
    if (current_token == log_token &&
        rinfs_shared_owner_query_row(mount, &current_row) == RINFS_OK &&
        current_row == row) {
        *token_out = log_token;
        return RINFS_OK;
    }
    *token_out = log_token;
    return RINFS_OK;
}

static int rinfs_shared_lock_acquire(RinFS_Mount* mount,
                                     volatile uint32_t* lock,
                                     int* recovered_out,
                                     uint32_t* recovered_owner_token_out)
    __attribute__((warn_unused_result));

static int rinfs_shared_lock_acquire(RinFS_Mount* mount,
                                     volatile uint32_t* lock,
                                     int* recovered_out,
                                     uint32_t* recovered_owner_token_out) {
    uint32_t spins = 0u;
    uint32_t token;
    int recovered = 0;
    if (recovered_out) *recovered_out = 0;
    if (recovered_owner_token_out) *recovered_owner_token_out = 0u;
    if (!lock) return RINFS_ERR_INVAL;
    token = rinfs_shared_lock_token(mount);
    if (token == 0u) return RINFS_ERR_CORRUPT;
    rinfs_spin_preempt_enter();
    for (;;) {
        uint32_t expected = 0u;
        if (__atomic_compare_exchange_n(lock, &expected, token, 0,
                                        __ATOMIC_ACQUIRE,
                                        __ATOMIC_RELAXED))
            break;
        {
            int owner_dead = rinfs_shared_lock_owner_dead(mount, expected);
            if (owner_dead < 0) {
                rinfs_shared_lock_fence(mount);
                rinfs_spin_preempt_leave();
                return RINFS_ERR_CORRUPT;
            }
            if (owner_dead) {
                uint32_t stale = expected;
                if (__atomic_compare_exchange_n(lock, &stale, token, 0,
                                                __ATOMIC_ACQUIRE,
                                                __ATOMIC_RELAXED)) {
                    recovered = 1;
                    if (recovered_owner_token_out)
                        *recovered_owner_token_out = expected;
                    break;
                }
            }
        }
        if (++spins == 4096u) {
#if defined(RIN_FREESTANDING) && !defined(RIN_KERNEL)
            platform_thread_yield();
#endif
            spins = 0u;
        }
        __asm__ volatile("pause");
    }
    if (recovered_out) *recovered_out = recovered;
    return RINFS_OK;
}

static int rinfs_shared_lock_release(RinFS_Mount* mount,
                                    volatile uint32_t* lock) {
    int result = RINFS_OK;
    uint32_t expected;
    if (!mount || !lock) {
        result = RINFS_ERR_INVAL;
    } else {
        expected = rinfs_shared_lock_token(mount);
        if (expected == 0u) {
            result = RINFS_ERR_CORRUPT;
        } else if (!__atomic_compare_exchange_n(
                       lock, &expected, 0u, 0, __ATOMIC_RELEASE,
                       __ATOMIC_RELAXED)) {
            /* Never clear a lock that was replaced by a newer owner. The
             * lock word carries a monotonic, non-wrapping SHM owner
             * generation, so this compare-and-clear is the release-side
             * counterpart of acquisition's exact-token publication. */
            rinfs_shared_lock_fence(mount);
            result = RINFS_ERR_STALE;
        }
    }
    /* Every call is paired with an acquisition that entered this guard,
     * including corruption paths where release must leave the lock intact. */
    rinfs_spin_preempt_leave();
    return result;
}

static int rinfs_shared_lock_error_after_release(int operation_error,
                                                  int release_error) {
    if (release_error != RINFS_OK &&
        (release_error != RINFS_ERR_ROFS || operation_error == RINFS_OK))
        return release_error;
    return operation_error;
}

static size_t rinfs_shared_heap_align(size_t value) {
    const size_t mask = (size_t)RINFS_SHARED_HEAP_ALIGNMENT - 1u;
    return value > (size_t)-1 - mask ? 0u : (value + mask) & ~mask;
}

static int rinfs_shared_heap_recover_locked(RinFS_Mount* mount) {
    const uint64_t header_bytes =
        rinfs_shared_heap_align(sizeof(RinFS_SharedHeapBlock));
    uint64_t arena_end;
    uint64_t offset;
    if (!mount || !mount->shared_mapping_base || header_bytes == 0u ||
        mount->shared_arena_offset == 0u ||
        mount->shared_mapping_size > UINT32_MAX) {
        if (mount) mount->shared_arena_recovery_failed = 1u;
        return 0;
    }
    arena_end = mount->shared_arena_offset + mount->shared_arena_size;
    if (arena_end < mount->shared_arena_offset ||
        arena_end > mount->shared_mapping_size) {
        mount->shared_arena_recovery_failed = 1u;
        return 0;
    }
    offset = mount->shared_arena_offset;
    while (offset < arena_end) {
        RinFS_SharedHeapBlock* block =
            (RinFS_SharedHeapBlock*)((uint8_t*)mount->shared_mapping_base +
                                    (size_t)offset);
        uint64_t remaining = arena_end - offset;
        uint64_t next_offset;
        if (remaining < header_bytes || block->magic !=
                RINFS_SHARED_HEAP_MAGIC || block->total_bytes < header_bytes ||
            block->total_bytes > remaining ||
            (block->total_bytes & (RINFS_SHARED_HEAP_ALIGNMENT - 1u)) != 0u ||
            block->is_free > 1u ||
            block->reserved >
                RINFS_SHARED_HEAP_REAP_PENDING_DELETE_PATH_ALLOCATION ||
            block->allocation_kind >
                RINFS_SHARED_HEAP_REAP_PENDING_DELETE_PATH_ALLOCATION) {
            mount->shared_arena_recovery_failed = 1u;
            return 0;
        }
        if (block->is_free && block->reserved != 0u) {
            block->reserved = 0u;
            block->owner_token = 0u;
            block->allocation_kind = 0u;
        } else if (block->is_free) {
            /* An interrupted allocation can leave an owner token on a free
             * block before its provisional state was published. */
            block->owner_token = 0u;
            block->allocation_kind = 0u;
        } else if (block->reserved ==
                       RINFS_SHARED_HEAP_REAP_PENDING_CONTENT_LEASE ||
                   block->reserved ==
                       RINFS_SHARED_HEAP_REAP_PENDING_DELETE_PATH) {
            if (block->owner_token != 0u ||
                block->allocation_kind != 0u) {
                mount->shared_arena_recovery_failed = 1u;
                return 0;
            }
        } else if (block->reserved ==
                       RINFS_SHARED_HEAP_REAP_PENDING_LEASE_ALLOCATION ||
                   block->reserved ==
                       RINFS_SHARED_HEAP_REAP_PENDING_DELETE_PATH_ALLOCATION) {
            if (block->owner_token == 0u ||
                block->allocation_kind != block->reserved) {
                mount->shared_arena_recovery_failed = 1u;
                return 0;
            }
        } else if (block->owner_token != 0u) {
            if (block->reserved != 0u ||
                (block->allocation_kind != 0u &&
                 block->allocation_kind !=
                     RINFS_SHARED_HEAP_REAP_PENDING_LEASE_ALLOCATION &&
                 block->allocation_kind !=
                     RINFS_SHARED_HEAP_REAP_PENDING_DELETE_PATH_ALLOCATION)) {
                mount->shared_arena_recovery_failed = 1u;
                return 0;
            }
            if (block->allocation_kind != 0u) {
                /* Publication clears the provisional state before its token.
                 * Restore the marker so dead-owner recovery can still
                 * distinguish a detached allocation from a reachable object. */
                __atomic_store_n(
                    &block->reserved,
                    block->allocation_kind,
                    __ATOMIC_RELEASE);
            } else {
                /* The owner had already cleared the provisional kind after
                 * linking the object and died before clearing its token. */
                block->owner_token = 0u;
            }
        } else if (block->allocation_kind != 0u) {
            mount->shared_arena_recovery_failed = 1u;
            return 0;
        }
        next_offset = offset + block->total_bytes;
        if (block->is_free && next_offset < arena_end) {
            RinFS_SharedHeapBlock* next =
                (RinFS_SharedHeapBlock*)((uint8_t*)mount->shared_mapping_base +
                                        (size_t)next_offset);
            uint64_t next_remaining = arena_end - next_offset;
            if (next_remaining < header_bytes || next->magic !=
                    RINFS_SHARED_HEAP_MAGIC ||
                next->total_bytes < header_bytes ||
                next->total_bytes > next_remaining ||
                (next->total_bytes &
                    (RINFS_SHARED_HEAP_ALIGNMENT - 1u)) != 0u ||
                next->is_free > 1u ||
                next->reserved >
                    RINFS_SHARED_HEAP_REAP_PENDING_DELETE_PATH_ALLOCATION ||
                next->allocation_kind >
                    RINFS_SHARED_HEAP_REAP_PENDING_DELETE_PATH_ALLOCATION) {
                mount->shared_arena_recovery_failed = 1u;
                return 0;
            }
            if (next->is_free) {
                /* Both sizes are 32-bit aligned stores. Repeating this merge
                 * after interruption is safe because the next block is no
                 * longer on the physical chain once total_bytes is stored. */
                block->total_bytes += next->total_bytes;
                continue;
            }
        }
        offset = next_offset;
    }
    if (offset != arena_end) {
        mount->shared_arena_recovery_failed = 1u;
        return 0;
    }
    return 1;
}

static int rinfs_shared_heap_lock(RinFS_Mount* mount) {
    int recovered = 0;
    int err = rinfs_shared_lock_acquire(
        mount, &mount->shared_arena_lock, &recovered, NULL);
    if (err != RINFS_OK) return err;
    if (recovered && !rinfs_shared_heap_recover_locked(mount)) {
        mount->shared_arena_recovery_failed = 1u;
        rinfs_shared_lock_fence(mount);
        return rinfs_shared_lock_error_after_release(
            RINFS_ERR_CORRUPT,
            rinfs_shared_lock_release(mount, &mount->shared_arena_lock));
    }
    return RINFS_OK;
}

static int rinfs_shared_heap_unlock(RinFS_Mount* mount) {
    return rinfs_shared_lock_release(mount, &mount->shared_arena_lock);
}

/* Mark a shared-heap object before unlinking it from its owning list. The
 * marker survives owner death in the interval between list removal and
 * allocator release; ordinary allocated blocks are never reaped this way. */
static int rinfs_shared_heap_mark_reaper_pending(
    RinFS_Mount* mount, void* pointer, uint32_t pending_kind) {
    const size_t header_bytes = rinfs_shared_heap_align(
        sizeof(RinFS_SharedHeapBlock));
    uintptr_t base;
    uintptr_t value;
    uint64_t offset;
    int result;
    if (!mount || !pointer || header_bytes == 0u ||
        (pending_kind != RINFS_SHARED_HEAP_REAP_PENDING_CONTENT_LEASE &&
         pending_kind != RINFS_SHARED_HEAP_REAP_PENDING_DELETE_PATH))
        return RINFS_ERR_INVAL;
    if (!mount->shared_mapping_base || mount->shared_arena_offset == 0u)
        return RINFS_OK;
    base = (uintptr_t)mount->shared_mapping_base;
    value = (uintptr_t)pointer;
    if (value < base ||
        (uint64_t)(value - base) >= mount->shared_mapping_size ||
        mount->shared_arena_offset > mount->shared_mapping_size ||
        header_bytes > mount->shared_mapping_size -
                           mount->shared_arena_offset ||
        (uint64_t)(value - base) <
            mount->shared_arena_offset + header_bytes ||
        ((value - base - header_bytes) &
         (RINFS_SHARED_HEAP_ALIGNMENT - 1u)) != 0u)
        return RINFS_ERR_CORRUPT;
    offset = (uint64_t)(value - base - header_bytes);
    result = rinfs_shared_heap_lock(mount);
    if (result != RINFS_OK) return result;
    if (offset < mount->shared_arena_offset ||
        offset > mount->shared_mapping_size - header_bytes) {
        result = RINFS_ERR_CORRUPT;
    } else {
        RinFS_SharedHeapBlock* target = (RinFS_SharedHeapBlock*)(
            (uint8_t*)mount->shared_mapping_base + (size_t)offset);
        if (target->magic != RINFS_SHARED_HEAP_MAGIC ||
            target->is_free != 0u || target->total_bytes < header_bytes ||
            target->total_bytes > mount->shared_mapping_size - offset ||
            (target->total_bytes &
             (RINFS_SHARED_HEAP_ALIGNMENT - 1u)) != 0u ||
            (target->reserved != 0u &&
             target->reserved != pending_kind) ||
            target->owner_token != 0u || target->allocation_kind != 0u) {
            result = RINFS_ERR_CORRUPT;
        } else {
            __atomic_store_n(&target->reserved, pending_kind,
                             __ATOMIC_RELEASE);
        }
    }
    {
        int unlock_error = rinfs_shared_heap_unlock(mount);
        if (result == RINFS_OK) result = unlock_error;
    }
    if (result == RINFS_ERR_CORRUPT) {
        mount->shared_arena_recovery_failed = 1u;
        rinfs_mount_force_readonly(mount);
    }
    return result;
}


static void* rinfs_mount_runtime_alloc(RinFS_Mount* mount, size_t size,
                                       uint32_t allocation_kind,
                                       int* error_out) {
    size_t header_bytes = rinfs_shared_heap_align(
        sizeof(RinFS_SharedHeapBlock));
    size_t payload_bytes;
    uint64_t offset;
    uint32_t allocation_owner_token = 0u;
    int error = RINFS_OK;
    if (allocation_kind != 0u &&
        allocation_kind !=
            RINFS_SHARED_HEAP_REAP_PENDING_LEASE_ALLOCATION &&
        allocation_kind !=
            RINFS_SHARED_HEAP_REAP_PENDING_DELETE_PATH_ALLOCATION) {
        if (error_out) *error_out = RINFS_ERR_INVAL;
        return NULL;
    }
    if (error_out) *error_out = RINFS_OK;
    if (!mount || !mount->shared_mapping_base ||
        mount->shared_arena_offset == 0u || size == 0u) {
        void* allocation = rinfs_malloc(size);
        if (!allocation) error = RINFS_ERR_NOMEM;
        if (error_out) *error_out = error;
        return allocation;
    }
    payload_bytes = rinfs_shared_heap_align(size);
    if (header_bytes == 0u || payload_bytes == 0u ||
        payload_bytes > UINT32_MAX - header_bytes ||
        payload_bytes > (size_t)-1 - header_bytes) {
        if (error_out) *error_out = RINFS_ERR_OVERFLOW;
        return NULL;
    }
    error = rinfs_shared_heap_lock(mount);
    if (error != RINFS_OK) {
        if (error_out) *error_out = error;
        return NULL;
    }
    if (mount->shared_arena_recovery_failed != 0u) {
        error = rinfs_shared_heap_unlock(mount);
        if (error == RINFS_OK) error = RINFS_ERR_ROFS;
        if (error_out) *error_out = error;
        return NULL;
    }
    if (mount->shared_mount_ready != 0u) {
        if (allocation_kind !=
                RINFS_SHARED_HEAP_REAP_PENDING_LEASE_ALLOCATION &&
            allocation_kind !=
                RINFS_SHARED_HEAP_REAP_PENDING_DELETE_PATH_ALLOCATION) {
            error = rinfs_shared_heap_unlock(mount);
            if (error == RINFS_OK) error = RINFS_ERR_INVAL;
            if (error_out) *error_out = error;
            return NULL;
        }
        allocation_owner_token = rinfs_shared_lock_token(mount);
        if (allocation_owner_token == 0u) {
            error = rinfs_shared_heap_unlock(mount);
            if (error == RINFS_OK) error = RINFS_ERR_STALE;
            if (error_out) *error_out = error;
            return NULL;
        }
    }
    offset = mount->shared_arena_offset;
    while (offset < mount->shared_mapping_size) {
        RinFS_SharedHeapBlock* block =
            (RinFS_SharedHeapBlock*)((uint8_t*)mount->shared_mapping_base +
                                    (size_t)offset);
        uint64_t remaining = mount->shared_mapping_size - offset;
        if (remaining < header_bytes || block->magic !=
                RINFS_SHARED_HEAP_MAGIC || block->total_bytes < header_bytes ||
            block->total_bytes > remaining ||
            (block->total_bytes & (RINFS_SHARED_HEAP_ALIGNMENT - 1u)) != 0u ||
            block->is_free > 1u ||
            block->reserved >
                RINFS_SHARED_HEAP_REAP_PENDING_DELETE_PATH_ALLOCATION ||
            block->allocation_kind >
                RINFS_SHARED_HEAP_REAP_PENDING_DELETE_PATH_ALLOCATION) {
            mount->shared_arena_recovery_failed = 1u;
            rinfs_shared_lock_fence(mount);
            error = rinfs_shared_heap_unlock(mount);
            if (error == RINFS_OK) error = RINFS_ERR_CORRUPT;
            if (error_out) *error_out = error;
            return NULL;
        }
        if (block->is_free && block->reserved != 0u) {
            block->reserved = 0u;
            block->owner_token = 0u;
            block->allocation_kind = 0u;
        }
        if (block->is_free && block->total_bytes >=
                (uint64_t)header_bytes + payload_bytes) {
            uint64_t required = (uint64_t)header_bytes + payload_bytes;
            uint64_t remainder = block->total_bytes - required;
            if (remainder >= (uint64_t)header_bytes +
                                 RINFS_SHARED_HEAP_ALIGNMENT) {
                RinFS_SharedHeapBlock* split =
                    (RinFS_SharedHeapBlock*)((uint8_t*)block + required);
                split->magic = RINFS_SHARED_HEAP_MAGIC;
                split->total_bytes = remainder;
                split->is_free = 1u;
                split->reserved = 0u;
                split->owner_token = 0u;
                split->allocation_kind = 0u;
                block->total_bytes = (uint32_t)required;
            }
            block->owner_token = allocation_owner_token;
            block->allocation_kind = allocation_owner_token != 0u
                                         ? allocation_kind
                                         : 0u;
            if (allocation_owner_token != 0u)
                __atomic_store_n(
                    &block->reserved,
                    allocation_kind,
                    __ATOMIC_RELEASE);
            else
                block->reserved = 0u;
            block->is_free = 0u;
            void* result = (uint8_t*)block + header_bytes;
            error = rinfs_shared_heap_unlock(mount);
            if (error != RINFS_OK) {
                /* The allocation was published, but the caller must not use
                 * it after the shared allocator lock could not be released. */
                if (error_out) *error_out = error;
                return NULL;
            }
            return result;
        }
        offset += block->total_bytes;
    }
    error = rinfs_shared_heap_unlock(mount);
    if (error == RINFS_OK) error = RINFS_ERR_NOMEM;
    if (error_out) *error_out = error;
    return NULL;
}

/* Clear the allocator's provisional owner marker only after the caller has
 * linked the object into its shared owner structure. If the owner dies before
 * this transition, owner recovery can distinguish a detached allocation from
 * a reachable object. */
static int rinfs_mount_runtime_publish(RinFS_Mount* mount, void* pointer) {
    size_t header_bytes = rinfs_shared_heap_align(
        sizeof(RinFS_SharedHeapBlock));
    uintptr_t base;
    uintptr_t value;
    uint64_t offset;
    uint32_t owner_token;
    int result;
    if (!mount || !pointer) return RINFS_ERR_INVAL;
    if (!mount->shared_mapping_base || mount->shared_arena_offset == 0u ||
        mount->shared_mount_ready == 0u)
        return RINFS_OK;
    if (header_bytes == 0u) return RINFS_ERR_CORRUPT;
    base = (uintptr_t)mount->shared_mapping_base;
    value = (uintptr_t)pointer;
    if (value < base ||
        (uint64_t)(value - base) >= mount->shared_mapping_size ||
        mount->shared_arena_offset > mount->shared_mapping_size ||
        header_bytes > mount->shared_mapping_size -
                           mount->shared_arena_offset ||
        (uint64_t)(value - base) <
            mount->shared_arena_offset + header_bytes ||
        ((value - base - header_bytes) &
         (RINFS_SHARED_HEAP_ALIGNMENT - 1u)) != 0u)
        return RINFS_ERR_CORRUPT;
    offset = (uint64_t)(value - base - header_bytes);
    owner_token = rinfs_shared_lock_token(mount);
    if (owner_token == 0u) return RINFS_ERR_STALE;
    result = rinfs_shared_heap_lock(mount);
    if (result != RINFS_OK) return result;
    if (offset < mount->shared_arena_offset ||
        offset > mount->shared_mapping_size - header_bytes) {
        result = RINFS_ERR_CORRUPT;
    } else {
        RinFS_SharedHeapBlock* target = (RinFS_SharedHeapBlock*)(
            (uint8_t*)mount->shared_mapping_base + (size_t)offset);
        if (target->magic != RINFS_SHARED_HEAP_MAGIC ||
            target->is_free != 0u || target->total_bytes < header_bytes ||
            target->total_bytes > mount->shared_mapping_size - offset ||
            (target->total_bytes &
             (RINFS_SHARED_HEAP_ALIGNMENT - 1u)) != 0u ||
            (target->reserved != 0u &&
             target->reserved !=
                 RINFS_SHARED_HEAP_REAP_PENDING_LEASE_ALLOCATION &&
             target->reserved !=
                 RINFS_SHARED_HEAP_REAP_PENDING_DELETE_PATH_ALLOCATION) ||
            (target->owner_token != 0u &&
             target->owner_token != owner_token) ||
            ((target->reserved ==
                  RINFS_SHARED_HEAP_REAP_PENDING_LEASE_ALLOCATION ||
              target->reserved ==
                  RINFS_SHARED_HEAP_REAP_PENDING_DELETE_PATH_ALLOCATION) &&
             (target->owner_token != owner_token ||
              target->allocation_kind != target->reserved)) ||
            (target->reserved == 0u && target->owner_token == 0u &&
             target->allocation_kind != 0u) ||
            (target->reserved == 0u && target->owner_token != 0u &&
             target->allocation_kind != 0u &&
             target->allocation_kind !=
                 RINFS_SHARED_HEAP_REAP_PENDING_LEASE_ALLOCATION &&
             target->allocation_kind !=
                 RINFS_SHARED_HEAP_REAP_PENDING_DELETE_PATH_ALLOCATION)) {
            result = RINFS_ERR_CORRUPT;
        } else {
            /* Recovery restores the marker until this linked object has
             * crossed publication. Clearing allocation_kind before token
             * leaves a distinct, recoverable final publication state. */
            __atomic_store_n(&target->reserved, 0u, __ATOMIC_RELEASE);
            target->allocation_kind = 0u;
            target->owner_token = 0u;
        }
    }
    {
        int unlock_error = rinfs_shared_heap_unlock(mount);
        if (result == RINFS_OK) result = unlock_error;
    }
    if (result == RINFS_ERR_CORRUPT) {
        mount->shared_arena_recovery_failed = 1u;
        rinfs_mount_force_readonly(mount);
    }
    return result;
}

static void rinfs_keep_first_error(int* first_error, int next_error);

static int rinfs_mount_runtime_free(RinFS_Mount* mount, void* pointer,
                                   int* released_out) {
    size_t header_bytes = rinfs_shared_heap_align(
        sizeof(RinFS_SharedHeapBlock));
    uintptr_t base;
    uintptr_t value;
    uint64_t offset;
    int error = RINFS_OK;
    if (released_out) *released_out = 0;
    if (!pointer) {
        if (released_out) *released_out = 1;
        return RINFS_OK;
    }
    if (!mount || !mount->shared_mapping_base ||
        mount->shared_arena_offset == 0u) {
        rinfs_free(pointer);
        if (released_out) *released_out = 1;
        return RINFS_OK;
    }
    base = (uintptr_t)mount->shared_mapping_base;
    value = (uintptr_t)pointer;
    if (value < base ||
        (uint64_t)(value - base) >= mount->shared_mapping_size) {
        rinfs_free(pointer);
        if (released_out) *released_out = 1;
        return RINFS_OK;
    }
    if (header_bytes == 0u ||
        mount->shared_arena_offset > mount->shared_mapping_size ||
        header_bytes > mount->shared_mapping_size -
                           mount->shared_arena_offset ||
        (uint64_t)(value - base) <
            mount->shared_arena_offset + header_bytes ||
        ((value - base - header_bytes) &
         (RINFS_SHARED_HEAP_ALIGNMENT - 1u)) != 0u) {
        rinfs_mount_force_readonly(mount);
        mount->shared_arena_recovery_failed = 1u;
        return RINFS_ERR_CORRUPT;
    }
    offset = (uint64_t)(value - base - header_bytes);
    error = rinfs_shared_heap_lock(mount);
    if (error != RINFS_OK) {
        rinfs_mount_force_readonly(mount);
        mount->shared_arena_recovery_failed = 1u;
        return error;
    }
    if (mount->shared_arena_recovery_failed != 0u) {
        error = RINFS_ERR_ROFS;
        rinfs_keep_first_error(&error, rinfs_shared_heap_unlock(mount));
        rinfs_mount_force_readonly(mount);
        return error;
    }
    if (offset < mount->shared_arena_offset ||
        offset > mount->shared_mapping_size - header_bytes) {
        error = RINFS_ERR_CORRUPT;
        goto corrupt_locked;
    }
    RinFS_SharedHeapBlock* target =
        (RinFS_SharedHeapBlock*)((uint8_t*)mount->shared_mapping_base +
                                (size_t)offset);
    if (target->magic != RINFS_SHARED_HEAP_MAGIC || target->is_free != 0u ||
        target->total_bytes < header_bytes ||
        target->total_bytes > mount->shared_mapping_size - offset ||
        (target->total_bytes &
         (RINFS_SHARED_HEAP_ALIGNMENT - 1u)) != 0u ||
        (target->reserved != 0u &&
         target->reserved !=
             RINFS_SHARED_HEAP_REAP_PENDING_CONTENT_LEASE &&
         target->reserved != RINFS_SHARED_HEAP_REAP_PENDING_DELETE_PATH &&
         target->reserved !=
             RINFS_SHARED_HEAP_REAP_PENDING_LEASE_ALLOCATION &&
         target->reserved !=
             RINFS_SHARED_HEAP_REAP_PENDING_DELETE_PATH_ALLOCATION) ||
        ((target->reserved ==
              RINFS_SHARED_HEAP_REAP_PENDING_LEASE_ALLOCATION ||
          target->reserved ==
              RINFS_SHARED_HEAP_REAP_PENDING_DELETE_PATH_ALLOCATION) &&
         (target->owner_token == 0u ||
          target->owner_token != rinfs_shared_lock_token(mount) ||
          target->allocation_kind != target->reserved)) ||
        (target->reserved == 0u && target->owner_token != 0u &&
         target->allocation_kind != 0u &&
         target->allocation_kind !=
             RINFS_SHARED_HEAP_REAP_PENDING_LEASE_ALLOCATION &&
         target->allocation_kind !=
             RINFS_SHARED_HEAP_REAP_PENDING_DELETE_PATH_ALLOCATION) ||
        (target->reserved == 0u && target->owner_token == 0u &&
         target->allocation_kind != 0u) ||
        (target->owner_token != 0u && target->reserved != 0u &&
         target->reserved !=
             RINFS_SHARED_HEAP_REAP_PENDING_LEASE_ALLOCATION &&
         target->reserved !=
             RINFS_SHARED_HEAP_REAP_PENDING_DELETE_PATH_ALLOCATION)) {
        error = RINFS_ERR_CORRUPT;
        goto corrupt_locked;
    }
    target->is_free = 1u;
    if (released_out) *released_out = 1;
    target->reserved = 0u;
    target->owner_token = 0u;
    target->allocation_kind = 0u;
    /* Coalesce adjacent free blocks so content lease churn cannot fragment
     * the fixed shared arena over a long-lived mount. */
    offset = mount->shared_arena_offset;
    while (offset < mount->shared_mapping_size) {
        RinFS_SharedHeapBlock* block =
            (RinFS_SharedHeapBlock*)((uint8_t*)mount->shared_mapping_base +
                                    (size_t)offset);
        uint64_t next_offset;
        if (block->magic != RINFS_SHARED_HEAP_MAGIC ||
            block->total_bytes < header_bytes ||
            block->total_bytes > mount->shared_mapping_size - offset ||
            (block->total_bytes &
             (RINFS_SHARED_HEAP_ALIGNMENT - 1u)) != 0u ||
            block->is_free > 1u ||
            block->reserved >
                RINFS_SHARED_HEAP_REAP_PENDING_DELETE_PATH_ALLOCATION ||
            block->allocation_kind >
                RINFS_SHARED_HEAP_REAP_PENDING_DELETE_PATH_ALLOCATION) {
            error = RINFS_ERR_CORRUPT;
            break;
        }
        next_offset = offset + block->total_bytes;
        if (block->is_free && next_offset < mount->shared_mapping_size) {
            RinFS_SharedHeapBlock* next =
                (RinFS_SharedHeapBlock*)((uint8_t*)mount->shared_mapping_base +
                                        (size_t)next_offset);
            if (next->magic != RINFS_SHARED_HEAP_MAGIC ||
                next->total_bytes < header_bytes ||
                next->total_bytes > mount->shared_mapping_size - next_offset ||
                (next->total_bytes &
                 (RINFS_SHARED_HEAP_ALIGNMENT - 1u)) != 0u ||
                next->is_free > 1u ||
                next->reserved >
                    RINFS_SHARED_HEAP_REAP_PENDING_DELETE_PATH_ALLOCATION ||
                next->allocation_kind >
                    RINFS_SHARED_HEAP_REAP_PENDING_DELETE_PATH_ALLOCATION) {
                error = RINFS_ERR_CORRUPT;
                break;
            }
            if (next->is_free) {
                block->total_bytes += next->total_bytes;
                continue;
            }
        }
        offset = next_offset;
    }
    if (error != RINFS_OK) {
        mount->shared_arena_recovery_failed = 1u;
        rinfs_mount_force_readonly(mount);
    }
    rinfs_keep_first_error(&error, rinfs_shared_heap_unlock(mount));
    if (error != RINFS_OK) {
        mount->shared_arena_recovery_failed = 1u;
        rinfs_mount_force_readonly(mount);
    }
    return error;

corrupt_locked:
    mount->shared_arena_recovery_failed = 1u;
    rinfs_mount_force_readonly(mount);
    rinfs_keep_first_error(&error, rinfs_shared_heap_unlock(mount));
    return error;
}

typedef struct RinFS_DeleteOnClosePath {
    struct RinFS_DeleteOnClosePath* next;
    uint64_t parent_inode;
    uint32_t parent_generation;
    uint32_t directory;
    uint64_t inode_num;
    uint32_t inode_generation;
    char name[RINFS_NAME_MAX + 1u];
    char path[1024];
} RinFS_DeleteOnClosePath;

typedef struct RinFS_ContentLeaseNode {
    struct RinFS_ContentLeaseNode* next;
    RinFS_DeleteOnClosePath* delete_on_close_paths;
    uint64_t inode_num;
    uint32_t inode_generation;
    uint64_t token_generation;
    uint32_t references;
    uint32_t readers;
    uint32_t waiting_writers;
    uint32_t writer;
    uint32_t open_references;
    uint32_t tracked_open_references;
    uint32_t wincompat_share_handle_count;
    uint32_t wincompat_share_access_counts[3];
    uint32_t wincompat_share_denied_counts[3];
    uint32_t delete_pending;
    uint32_t delete_on_close_count;
    uint32_t delete_on_close_reaping;
    uint32_t delete_on_close_reaping_owner_token;
    uint32_t delete_on_close_last_error;
    /* Per-process operation counts are the recovery journal for the
     * aggregate reader/writer state. A dead process row is excluded and the
     * aggregates can be rebuilt without guessing whether an operation had
     * reached its release path. */
    uint32_t shared_readers[RINFS_SHARED_OWNER_CAPACITY];
    uint32_t shared_writers[RINFS_SHARED_OWNER_CAPACITY];
    uint32_t shared_waiting_readers[RINFS_SHARED_OWNER_CAPACITY];
    uint32_t shared_waiting_writers[RINFS_SHARED_OWNER_CAPACITY];
} RinFS_ContentLeaseNode;

static void rinfs_delete_on_close_reaping_clear_locked(
    RinFS_ContentLeaseNode* lease) {
    if (!lease) return;
    __atomic_store_n(&lease->delete_on_close_reaping, 0u, __ATOMIC_RELEASE);
    lease->delete_on_close_reaping_owner_token = 0u;
}

static int rinfs_delete_on_close_reaping_begin_locked(
    RinFS_Mount* mount, RinFS_ContentLeaseNode* lease) {
    uint32_t owner_token;
    if (!mount || !lease) return RINFS_ERR_INVAL;
    owner_token = rinfs_shared_lock_token(mount);
    if (owner_token == 0u) return RINFS_ERR_CORRUPT;
    lease->delete_on_close_reaping_owner_token = owner_token;
    __atomic_store_n(&lease->delete_on_close_reaping, 1u, __ATOMIC_RELEASE);
    return RINFS_OK;
}

typedef struct RinFS_CloseReferenceRecord {
    uint32_t in_use;
    uint32_t kind;
    uint32_t state;
    uint32_t reserved;
    RinFS_Mount* mount;
    uint64_t mount_epoch;
    uint64_t inode_num;
    uint32_t inode_generation;
    uint32_t reserved2;
    uint64_t content_pin_token;
    uint64_t generation;
    uint64_t cookie;
    uint32_t wincompat_share_access;
    uint32_t wincompat_share_mode;
    uint32_t wincompat_share_registered;
    uint32_t active_operations;
    /* One-based kernel-owned shared-mount owner row; zero for private mounts. */
    uint32_t shared_owner_row;
} RinFS_CloseReferenceRecord;

#define RINFS_MAX_CLOSE_REFERENCES 512u
#define RINFS_CLOSE_REF_FILE 1u
#define RINFS_CLOSE_REF_DIRECTORY 2u
#define RINFS_CLOSE_REF_RESERVED 1u
#define RINFS_CLOSE_REF_ACTIVE 2u
#define RINFS_CLOSE_REF_CLOSING 3u
#define RINFS_CLOSE_REF_RELEASED 4u
#define RINFS_CLOSE_REF_PRIMARY_DOMAIN UINT64_C(0x52494E4653435250)
#define RINFS_CLOSE_REF_MIRROR_DOMAIN UINT64_C(0x52494E465343524D)
#define RINFS_CLOSE_REF_RECOVERY_DOMAIN UINT64_C(0x52494E4653435252)
#define RINFS_CLOSE_REF_WITNESS_DOMAIN UINT64_C(0x52494E4653435257)

/* Lock ordering for cross-layer callers is fixed: mount lifecycle gate,
 * file position lock, inode-object lease (inode number order for batches),
 * inode-table/allocator/journal locks, then the verified-backing cache.  The
 * content lease itself is inode-scoped; it never serializes unrelated files
 * or holds the cache lock across filesystem I/O. */

#define RINFS_MMAP_SOURCE_MAGIC UINT64_C(0x52494E4D4D415031)

struct RinFS_MmapSource {
    uint64_t magic;
    RinFS_Mount* mount;
    uint64_t inode_num;
    uint64_t pin_token;
    uint32_t inode_generation;
    uint32_t shared_owner_row;
    uint64_t reference_generation;
    uint64_t reference_cookie;
} __attribute__((aligned(8)));

#define RINFS_MAX_MMAP_SOURCE_REFERENCES 1024u
#define RINFS_MMAP_SOURCE_ACTIVE 1u
#define RINFS_MMAP_SOURCE_RETIRING 2u
