/* Unlink (delete) a file */
static int rinfs_unlink_internal(RinFS_Mount* mount, uint64_t dir_ino,
                                 const char* name, uint64_t expected_inode,
                                 uint32_t expected_generation) {
    int content_unlock_error = RINFS_OK;
    RinFS_ContentLeaseNode* lease = NULL;
    uint64_t lease_token = 0u;
    uint32_t inode_generation;
    int defer_reclaim;
    if (!mount || !mount->mounted || !name) return rinfs_content_unlock_status((RINFS_ERR_INVAL), content_unlock_error);
    int prepare_error = rinfs_mount_prepare_write(mount);
    if (prepare_error != RINFS_OK)
        return rinfs_content_unlock_status(
            prepare_error, content_unlock_error);
    
    /* Look up the file */
    uint64_t file_ino;
    int err = rinfs_lookup(mount, dir_ino, name, &file_ino);
    if (err != RINFS_OK) return rinfs_content_unlock_status((err), content_unlock_error);
    if (expected_inode != 0u && file_ino != expected_inode)
        return rinfs_content_unlock_status((RINFS_ERR_STALE), content_unlock_error);
    
    /* Read file inode */
    RinFS_Inode file_inode;
    err = rinfs_inode_read(mount, file_ino, &file_inode);
    if (err != RINFS_OK) return rinfs_content_unlock_status((err), content_unlock_error);
    inode_generation = file_inode.i_generation;
    if (expected_generation != 0u &&
        inode_generation != expected_generation)
        return rinfs_content_unlock_status((RINFS_ERR_STALE), content_unlock_error);
    err = rinfs_content_lease_acquire(mount, file_ino,
                                      inode_generation, 1,
                                      &lease, &lease_token);
    if (err != RINFS_OK) return rinfs_content_unlock_status((err), content_unlock_error);
    err = rinfs_inode_read(mount, file_ino, &file_inode);
    if (err != RINFS_OK || file_inode.i_generation != inode_generation) {
        rinfs_keep_first_error(&content_unlock_error, rinfs_content_lease_release(mount, file_ino, inode_generation,
                                    lease_token, 1));
        return rinfs_content_unlock_status((err == RINFS_OK ? RINFS_ERR_STALE : err), content_unlock_error);
    }
    
    /* Check it's not a directory */
    if ((file_inode.i_mode >> 12) == RINFS_FT_DIR) {
        rinfs_keep_first_error(&content_unlock_error, rinfs_content_lease_release(mount, file_ino, inode_generation,
                                    lease_token, 1));
        return rinfs_content_unlock_status((RINFS_ERR_ISDIR), content_unlock_error);  /* Use rmdir for directories */
    }
    if (file_inode.i_links == 0) {
        rinfs_keep_first_error(&content_unlock_error, rinfs_content_lease_release(mount, file_ino, inode_generation,
                                    lease_token, 1));
        return rinfs_content_unlock_status((RINFS_ERR_CORRUPT), content_unlock_error);
    }

    /* Publish recovery intent before the parent entry can disappear. If the
     * directory mutation never commits, mount recovery observes the still
     * reachable inode and simply clears this marker. */
    err = rinfs_inode_orphan_commit(mount, file_ino, &file_inode, 1);
    if (err != RINFS_OK) {
        rinfs_keep_first_error(&content_unlock_error, rinfs_content_lease_release(mount, file_ino, inode_generation,
                                    lease_token, 1));
        return rinfs_content_unlock_status((err), content_unlock_error);
    }
    
    /* Remove directory entry */
    err = rinfs_dirent_remove_identity(mount, dir_ino, name,
                                       expected_inode);
    if (err != RINFS_OK) {
        /* Removal may have reached storage despite its reported error. Keep
         * ORPHAN_INTENT so the next mount can recount names and repair or
         * reclaim the inode, and stop mutations until that recovery runs. */
        rinfs_mount_force_readonly(mount);
        rinfs_keep_first_error(&content_unlock_error, rinfs_content_lease_release(mount, file_ino, inode_generation,
                                    lease_token, 1));
        return rinfs_content_unlock_status((err), content_unlock_error);
    }
    
    /* Decrement link count */
    file_inode.i_links--;
    
    if (file_inode.i_links == 0) {
        defer_reclaim = rinfs_content_delete_mark(
            mount, file_ino, inode_generation);
        if (defer_reclaim) {
            /* Keep size/map/data intact for existing open file objects. The
             * final close reclaims this zero-link lifetime. */
            err = rinfs_inode_orphan_commit(
                mount, file_ino, &file_inode, 1);
            rinfs_keep_first_error(&content_unlock_error, rinfs_content_lease_release(mount, file_ino,
                                        inode_generation, lease_token, 1));
            return rinfs_content_unlock_status((err), content_unlock_error);
        }
        /* No more links - detach all direct/indirect blocks before making
         * their bitmap entries reusable. */
        file_inode.i_size = 0;
        err = rinfs_inode_release_from(mount, file_ino, &file_inode, 0, 1);
        if (err == RINFS_OK)
            err = rinfs_inode_free_under_lease(mount, file_ino,
                                                inode_generation);
        if (err == RINFS_OK)
            rinfs_keep_first_error(&content_unlock_error, rinfs_content_delete_clear(mount, file_ino, inode_generation,
                                       lease_token));
    } else {
        /* Just update the inode */
        err = rinfs_inode_orphan_commit(
            mount, file_ino, &file_inode, 0);
    }
    rinfs_keep_first_error(&content_unlock_error, rinfs_content_lease_release(mount, file_ino, inode_generation,
                                lease_token, 1));
    if (err != RINFS_OK) {
        return rinfs_content_unlock_status((err), content_unlock_error);
    }
    return rinfs_content_unlock_status((RINFS_OK), content_unlock_error);
}

int rinfs_unlink(RinFS_Mount* mount, uint64_t dir_ino, const char* name) {
    return rinfs_unlink_internal(mount, dir_ino, name, 0u, 0u);
}

int rinfs_unlink_expected(RinFS_Mount* mount, uint64_t dir_ino,
                          const char* name, uint64_t expected_inode,
                          uint32_t expected_generation) {
    if (expected_inode == 0u || expected_generation == 0u)
        return RINFS_ERR_INVAL;
    return rinfs_unlink_internal(mount, dir_ino, name, expected_inode,
                                  expected_generation);
}

static int rinfs_unlink_entry_expected_unscoped(
    RinFS_Mount* mount, uint64_t parent_ino, uint32_t parent_generation,
    const char* name, uint64_t expected_inode,
    uint32_t expected_generation) {
    RinFS_Inode parent_inode;
    int result;
    if (!mount || !name || parent_ino == 0u || parent_generation == 0u ||
        expected_inode == 0u || expected_generation == 0u)
        return RINFS_ERR_INVAL;
    result = rinfs_journal_transaction_lock(mount);
    if (result != RINFS_OK) return result;
    result = rinfs_inode_read(mount, parent_ino, &parent_inode);
    if (result == RINFS_OK &&
        (parent_inode.i_generation != parent_generation ||
         (parent_inode.i_mode >> 12u) != RINFS_FT_DIR))
        result = RINFS_ERR_STALE;
    if (result == RINFS_OK)
        result = rinfs_unlink_internal(mount, parent_ino, name,
                                       expected_inode, expected_generation);
    return rinfs_journal_transaction_unlock_status(mount, result);
}

/* Remove an empty directory after closing mutation races with its open
 * lifetime. expected_inode/generation are optional for ordinary rmdir; the
 * DELETE_ON_CLOSE path supplies both to prevent deleting a replacement. */
static int rinfs_rmdir_internal(RinFS_Mount* mount, uint64_t parent_ino,
                                const char* name, uint64_t expected_inode,
                                uint32_t expected_generation) {
    int content_unlock_error = RINFS_OK;
    RinFS_ContentLeaseNode* lease = NULL;
    uint64_t lease_token = 0u;
    uint32_t inode_generation;
    int journal_enabled;
    int defer_reclaim;
    if (!mount || !mount->mounted || !name ||
        ((expected_inode == 0u) != (expected_generation == 0u)))
        return rinfs_content_unlock_status((RINFS_ERR_INVAL), content_unlock_error);
    int prepare_error = rinfs_mount_prepare_write(mount);
    if (prepare_error != RINFS_OK)
        return rinfs_content_unlock_status(
            prepare_error, content_unlock_error);
    
    /* Cannot remove . or .. */
    if (rinfs_strcmp(name, ".") == 0 || rinfs_strcmp(name, "..") == 0) {
        return rinfs_content_unlock_status((RINFS_ERR_INVAL), content_unlock_error);
    }
    
    /* Look up the directory */
    uint64_t dir_ino;
    int err = rinfs_lookup(mount, parent_ino, name, &dir_ino);
    if (err != RINFS_OK) return rinfs_content_unlock_status((err), content_unlock_error);
    if (expected_inode != 0u && dir_ino != expected_inode)
        return rinfs_content_unlock_status((RINFS_ERR_STALE), content_unlock_error);
    
    /* Read directory inode */
    RinFS_Inode dir_inode;
    err = rinfs_inode_read(mount, dir_ino, &dir_inode);
    if (err != RINFS_OK) return rinfs_content_unlock_status((err), content_unlock_error);
    
    /* Check it's a directory */
    if ((dir_inode.i_mode >> 12) != RINFS_FT_DIR) {
        return rinfs_content_unlock_status((RINFS_ERR_NOTDIR), content_unlock_error);
    }

    inode_generation = dir_inode.i_generation;
    if (expected_generation != 0u &&
        inode_generation != expected_generation)
        return rinfs_content_unlock_status((RINFS_ERR_STALE), content_unlock_error);
    err = rinfs_content_lease_acquire(mount, dir_ino, inode_generation, 1,
                                      &lease, &lease_token);
    if (err != RINFS_OK) return rinfs_content_unlock_status((err), content_unlock_error);
    {
        RinFS_Inode live_inode;
        err = rinfs_inode_read(mount, dir_ino, &live_inode);
        if (err != RINFS_OK ||
            !rinfs_content_inode_equal(mount, &dir_inode, &live_inode) ||
            (expected_generation != 0u &&
             live_inode.i_generation != expected_generation)) {
            rinfs_keep_first_error(&content_unlock_error, rinfs_content_lease_release(mount, dir_ino, inode_generation,
                                        lease_token, 1));
            return rinfs_content_unlock_status((err == RINFS_OK ? RINFS_ERR_STALE : err), content_unlock_error);
        }
        dir_inode = live_inode;
    }

    /* Hold the directory's exclusive content lease while checking emptiness;
     * no child create/remove can race between this check and the parent entry
     * commit. */
    err = rinfs_dir_is_effectively_empty(mount, dir_ino, &dir_inode);
    if (err != RINFS_OK) {
        rinfs_keep_first_error(&content_unlock_error, rinfs_content_lease_release(mount, dir_ino, inode_generation,
                                    lease_token, 1));
        return rinfs_content_unlock_status((err), content_unlock_error);
    }

    /* Orphan intent is the recovery record for legacy volumes too. Upgrade
     * the incompatible feature before touching the namespace so older kernels
     * cannot reinterpret its inode metadata. */
    err = rinfs_enable_content_versions(mount);
    if (err != RINFS_OK) {
        rinfs_mount_force_readonly(mount);
        rinfs_keep_first_error(&content_unlock_error, rinfs_content_lease_release(mount, dir_ino, inode_generation,
                                    lease_token, 1));
        return rinfs_content_unlock_status((err), content_unlock_error);
    }
    journal_enabled =
        (mount->sb.s_compat_features &
         RINFS_FEATURE_COMPAT_RENAME_JOURNAL) != 0u;
    if (journal_enabled) {
        err = rinfs_journal_begin_rmdir(mount, parent_ino, name, dir_ino);
        if (err != RINFS_OK) {
            rinfs_mount_recovery_fence(
                mount, RINFS_READONLY_RECOVERY_NAMESPACE_JOURNAL, err);
            rinfs_keep_first_error(&content_unlock_error, rinfs_content_lease_release(mount, dir_ino, inode_generation,
                                        lease_token, 1));
            return rinfs_content_unlock_status((err), content_unlock_error);
        }
    }

    err = rinfs_inode_orphan_commit(mount, dir_ino, &dir_inode, 1);
    if (err != RINFS_OK) {
        if (journal_enabled)
            rinfs_mount_recovery_fence(
                mount, RINFS_READONLY_RECOVERY_NAMESPACE_JOURNAL, err);
        else
            rinfs_mount_force_readonly(mount);
        rinfs_keep_first_error(&content_unlock_error, rinfs_content_lease_release(mount, dir_ino, inode_generation,
                                    lease_token, 1));
        return rinfs_content_unlock_status((err), content_unlock_error);
    }
    
    /* Remove directory entry from parent */
    err = rinfs_dirent_remove_identity(mount, parent_ino, name, dir_ino);
    if (err != RINFS_OK) {
        if (journal_enabled)
            rinfs_mount_recovery_fence(
                mount, RINFS_READONLY_RECOVERY_NAMESPACE_JOURNAL, err);
        else
            rinfs_mount_force_readonly(mount);
        rinfs_keep_first_error(&content_unlock_error, rinfs_content_lease_release(mount, dir_ino, inode_generation,
                                    lease_token, 1));
        return rinfs_content_unlock_status((err), content_unlock_error);
    }

    dir_inode.i_links = 0u;
    err = rinfs_inode_orphan_commit(mount, dir_ino, &dir_inode, 1);
    if (err != RINFS_OK) {
        if (journal_enabled)
            rinfs_mount_recovery_fence(
                mount, RINFS_READONLY_RECOVERY_NAMESPACE_JOURNAL, err);
        else
            rinfs_mount_force_readonly(mount);
        rinfs_keep_first_error(&content_unlock_error, rinfs_content_lease_release(mount, dir_ino, inode_generation,
                                    lease_token, 1));
        return rinfs_content_unlock_status((err), content_unlock_error);
    }
    defer_reclaim = rinfs_content_delete_mark(
        mount, dir_ino, inode_generation);

    /* Keep the zero-link inode and journal record until the parent link count
     * is durably recounted. Mount recovery replays this exact step if power is
     * lost after the dentry commit. */
    err = rinfs_dir_recount_links(mount, parent_ino);
    if (err != RINFS_OK) {
        if (journal_enabled)
            rinfs_mount_recovery_fence(
                mount, RINFS_READONLY_RECOVERY_NAMESPACE_JOURNAL, err);
        else
            rinfs_mount_force_readonly(mount);
        rinfs_keep_first_error(&content_unlock_error, rinfs_content_lease_release(mount, dir_ino, inode_generation,
                                    lease_token, 1));
        return rinfs_content_unlock_status((err), content_unlock_error);
    }
    if (journal_enabled) {
        err = rinfs_journal_finish(mount);
        if (err != RINFS_OK) {
            rinfs_mount_recovery_fence(
                mount, RINFS_READONLY_RECOVERY_NAMESPACE_JOURNAL, err);
            rinfs_keep_first_error(&content_unlock_error, rinfs_content_lease_release(mount, dir_ino, inode_generation,
                                        lease_token, 1));
            return rinfs_content_unlock_status((err), content_unlock_error);
        }
    }

    if (defer_reclaim) {
        rinfs_keep_first_error(&content_unlock_error, rinfs_content_lease_release(mount, dir_ino, inode_generation,
                                    lease_token, 1));
        return rinfs_content_unlock_status((RINFS_OK), content_unlock_error);
    }

    /* The journal, when available, is clear and the orphan intent remains
     * durable. A crash in reclamation is completed by mount-time orphan
     * recovery. */
    dir_inode.i_size = 0u;
    err = rinfs_inode_release_from(mount, dir_ino, &dir_inode, 0u, 1);
    if (err == RINFS_OK)
        err = rinfs_inode_free_under_lease(mount, dir_ino, inode_generation);
    if (err == RINFS_OK)
        rinfs_keep_first_error(&content_unlock_error, rinfs_content_delete_clear(mount, dir_ino, inode_generation,
                                   lease_token));
    if (err != RINFS_OK) rinfs_mount_force_readonly(mount);
    rinfs_keep_first_error(&content_unlock_error, rinfs_content_lease_release(mount, dir_ino, inode_generation,
                                lease_token, 1));

    return rinfs_content_unlock_status((err), content_unlock_error);
}

/* Remove an empty directory. */
int rinfs_rmdir(RinFS_Mount* mount, uint64_t parent_ino, const char* name) {
    int result;
    if (!mount) return RINFS_ERR_INVAL;
    result = rinfs_journal_transaction_lock(mount);
    if (result != RINFS_OK) return result;
    result = rinfs_rmdir_internal(mount, parent_ino, name, 0u, 0u);
    return rinfs_journal_transaction_unlock_status(mount, result);
}

int rinfs_rmdir_expected(RinFS_Mount* mount, uint64_t parent_ino,
                         const char* name, uint64_t expected_inode,
                         uint32_t expected_generation) {
    if (expected_inode == 0u || expected_generation == 0u)
        return RINFS_ERR_INVAL;
    if (!mount) return RINFS_ERR_INVAL;
    int lock_err = rinfs_journal_transaction_lock(mount);
    if (lock_err != RINFS_OK) return lock_err;
    {
        int result = rinfs_rmdir_internal(
            mount, parent_ino, name, expected_inode, expected_generation);
        return rinfs_journal_transaction_unlock_status(mount, result);
    }
}

static int rinfs_rmdir_entry_expected_unscoped(
    RinFS_Mount* mount, uint64_t parent_ino, uint32_t parent_generation,
    const char* name, uint64_t expected_inode,
    uint32_t expected_generation) {
    RinFS_Inode parent_inode;
    int result;
    if (!mount || !name || parent_ino == 0u || parent_generation == 0u ||
        expected_inode == 0u || expected_generation == 0u)
        return RINFS_ERR_INVAL;
    result = rinfs_journal_transaction_lock(mount);
    if (result != RINFS_OK) return result;
    result = rinfs_inode_read(mount, parent_ino, &parent_inode);
    if (result == RINFS_OK &&
        (parent_inode.i_generation != parent_generation ||
         (parent_inode.i_mode >> 12u) != RINFS_FT_DIR))
        result = RINFS_ERR_STALE;
    if (result == RINFS_OK)
        result = rinfs_rmdir_internal(mount, parent_ino, name,
                                      expected_inode, expected_generation);
    return rinfs_journal_transaction_unlock_status(mount, result);
}

/* ═══════════════════════════════════════════════════════════════
 * Link Operations
 * ═══════════════════════════════════════════════════════════════*/

/* Create a hard link */
static int rinfs_link_unscoped(RinFS_Mount* mount, uint64_t dir_ino,
                               const char* name, uint64_t target_ino) {
    if (!mount || !mount->mounted || !name) return RINFS_ERR_INVAL;
    int err = rinfs_mount_prepare_write(mount);
    if (err != RINFS_OK) return err;

    /* Check if name already exists */
    uint64_t existing;
    if (rinfs_lookup(mount, dir_ino, name, &existing) == RINFS_OK) {
        return RINFS_ERR_EXIST;
    }

    /* Read target inode */
    RinFS_Inode target_inode;
    err = rinfs_inode_read(mount, target_ino, &target_inode);
    if (err != RINFS_OK) return err;

    /* Cannot hard link directories */
    if ((target_inode.i_mode >> 12) == RINFS_FT_DIR) {
        return RINFS_ERR_ISDIR;
    }
    if (target_inode.i_links >= RINFS_LINK_MAX) {
        return RINFS_ERR_EMLINK;
    }

    /* Add directory entry pointing to target */
    uint8_t file_type = target_inode.i_mode >> 12;
    err = rinfs_dirent_add(mount, dir_ino, name, target_ino, file_type);
    if (err != RINFS_OK) return err;

    /* Increment link count on target */
    target_inode.i_links++;
    rinfs_touch_changed(&target_inode);
    err = rinfs_inode_write(mount, target_ino, &target_inode);
    if (err != RINFS_OK) {
        /* The directory entry and inode count are one namespace mutation.
         * If the inode publication fails, remove the just-created entry so
         * a retry cannot observe a name whose link count was never committed. */
        int rollback_error = rinfs_dirent_remove(mount, dir_ino, name);
        if (rollback_error != RINFS_OK) {
            rinfs_mount_force_readonly(mount);
            return rollback_error;
        }
    }

    return err;
}

/* First link of an anonymous file is a small recoverable namespace protocol:
 * the dentry block is durable first, then the inode link count is committed
 * while ORPHAN_INTENT remains set, and finally the intent is cleared. Mount
 * recovery recounts directory references for marked inodes, so every crash
 * boundary resolves to either a live named inode or a reclaimed anonymous
 * inode. */
static int rinfs_link_tmpfile_core(RinFS_File* file, uint64_t dir_ino,
                                   const char* name) {
    int content_unlock_error = RINFS_OK;
    RinFS_Mount* mount;
    RinFS_ContentLeaseNode* lease = NULL;
    uint64_t lease_token = 0u;
    RinFS_Inode inode;
    RinFS_Inode parent_inode;
    uint64_t existing_ino = 0u;
    uint32_t observed_links = 0u;
    int result;

    if (!name || file->inode_num == 0u || file->content_pin_token == 0u)
        return rinfs_content_unlock_status((RINFS_ERR_INVAL), content_unlock_error);
    mount = file->mount;
    if (!mount->mounted)
        return rinfs_content_unlock_status(
            RINFS_ERR_ROFS, content_unlock_error);
    result = rinfs_mount_prepare_write(mount);
    if (result != RINFS_OK)
        return rinfs_content_unlock_status(
            result, content_unlock_error);
    if (!rinfs_mount_has_content_versions(mount))
        return rinfs_content_unlock_status((RINFS_ERR_NOT_SUPPORTED), content_unlock_error);
    if (dir_ino == 0u || dir_ino > mount->sb.s_inode_count)
        return rinfs_content_unlock_status((RINFS_ERR_INVAL), content_unlock_error);
    result = rinfs_content_lease_acquire(
        mount, file->inode_num, file->content_pin_generation, 1,
        &lease, &lease_token);
    if (result != RINFS_OK) return rinfs_content_unlock_status((result), content_unlock_error);
    if (lease_token != file->content_pin_token) {
        result = RINFS_ERR_STALE;
        goto done;
    }
    result = rinfs_inode_read(mount, file->inode_num, &inode);
    if (result != RINFS_OK) goto done;
    if (inode.i_generation != file->content_pin_generation ||
        (inode.i_mode >> 12u) != RINFS_FT_REG ||
        inode.i_links != 0u ||
        (inode.i_flags & RINFS_IFLG_ORPHAN_INTENT) == 0u) {
        result = RINFS_ERR_STALE;
        goto done;
    }
    result = rinfs_inode_read(mount, dir_ino, &parent_inode);
    if (result != RINFS_OK) goto done;
    if ((parent_inode.i_mode >> 12u) != RINFS_FT_DIR) {
        result = RINFS_ERR_NOTDIR;
        goto done;
    }
    if ((parent_inode.i_flags & (RINFS_IFLG_IMMUT | RINFS_IFLG_APPEND)) != 0u) {
        result = RINFS_ERR_INVAL;
        goto done;
    }
    result = rinfs_lookup(mount, dir_ino, name, &existing_ino);
    if (result == RINFS_OK) {
        result = RINFS_ERR_EXIST;
        goto done;
    }
    if (result != RINFS_ERR_NOENT) goto done;

    result = rinfs_dirent_add(mount, dir_ino, name, file->inode_num,
                              RINFS_FT_REG);
    if (result != RINFS_OK) {
        int lookup = rinfs_lookup(mount, dir_ino, name, &existing_ino);
        if (lookup != RINFS_OK || existing_ino != file->inode_num)
            goto done;
        /* The namespace block can be committed even if the caller reports a
         * later readback error. Continue the same idempotent publication. */
    }

    result = rinfs_inode_read(mount, file->inode_num, &inode);
    if (result != RINFS_OK) goto done;
    if (inode.i_generation != file->content_pin_generation ||
        (inode.i_flags & RINFS_IFLG_ORPHAN_INTENT) == 0u) {
        result = RINFS_ERR_STALE;
        goto done;
    }
    result = rinfs_count_inode_namespace_links(mount, file->inode_num,
                                                &observed_links);
    if (result != RINFS_OK) goto done;
    if (observed_links == 0u) {
        result = RINFS_ERR_IO;
        goto done;
    }
    inode.i_links = observed_links;
    result = rinfs_inode_orphan_commit(mount, file->inode_num, &inode, 1);
    if (result == RINFS_OK)
        result = rinfs_inode_orphan_commit(mount, file->inode_num, &inode, 0);
    if (result != RINFS_OK) {
        RinFS_Inode observed;
        int read_result = rinfs_inode_read(mount, file->inode_num, &observed);
        if (read_result != RINFS_OK ||
            observed.i_generation != file->content_pin_generation ||
            observed.i_links == 0u) {
            goto done;
        }
        /* The durable name is visible. Keep the open lifetime from trying to
         * reclaim it; mount recovery will reconcile the retained marker. */
        file->inode = observed;
        rinfs_keep_first_error(&content_unlock_error, rinfs_content_delete_clear(mount, file->inode_num,
                                   file->content_pin_generation,
                                   lease_token));
        goto done;
    }
    file->inode = inode;
    rinfs_keep_first_error(&content_unlock_error, rinfs_content_delete_clear(mount, file->inode_num,
                               file->content_pin_generation,
                               lease_token));

done:
    rinfs_keep_first_error(&content_unlock_error, rinfs_content_lease_release(mount, file->inode_num,
                                file->content_pin_generation, lease_token, 1));
    return rinfs_content_unlock_status((result), content_unlock_error);
}

int rinfs_link_tmpfile(RinFS_File* file, uint64_t dir_ino,
                       const char* name) {
    RinFS_CloseReferenceOperationLease operation;
    int result = rinfs_file_operation_begin(file, &operation);
    int release_result;
    if (result != RINFS_OK) return result;
    result = rinfs_link_tmpfile_core(file, dir_ino, name);
    release_result = rinfs_close_ref_end_operation(&operation);
    return release_result == RINFS_OK ? result : release_result;
}

/* Create a symbolic link */
static int rinfs_symlink_owned_unscoped(
    RinFS_Mount* mount, uint64_t dir_ino, const char* name,
    const char* target, uint32_t uid, uint32_t gid) {
    if (!mount || !mount->mounted || !name || !target) return RINFS_ERR_INVAL;
    int prepare_error = rinfs_mount_prepare_write(mount);
    if (prepare_error != RINFS_OK) return prepare_error;

    uint32_t target_len = rinfs_strlen(target);
    if (target_len == 0 || target_len >= RINFS_SYMLINK_MAX) {
        return RINFS_ERR_INVAL;
    }

    /* Check if name already exists */
    uint64_t existing;
    if (rinfs_lookup(mount, dir_ino, name, &existing) == RINFS_OK) {
        return RINFS_ERR_EXIST;
    }

    /* Allocate new inode for symlink */
    uint64_t link_ino;
    int err = rinfs_inode_alloc(mount, &link_ino);
    if (err != RINFS_OK) return err;

    /* Initialize symlink inode */
    RinFS_Inode link_inode;
    err = rinfs_prepare_new_inode(mount, link_ino, &link_inode);
    if (err != RINFS_OK) {
        rinfs_inode_free(mount, link_ino);
        return err;
    }
    link_inode.i_mode = (RINFS_FT_LNK << 12) | 0777; /* lrwxrwxrwx */
    link_inode.i_uid = uid;
    link_inode.i_gid = gid;
    link_inode.i_links = 1;
    link_inode.i_size = target_len;
    rinfs_touch_created(&link_inode);

    /* Store symlink target in data blocks or inline */
    if (target_len < sizeof(link_inode.i_block)) {
        /* Fast symlink: store target path in inode block pointers area */
        rinfs_memcpy(link_inode.i_block, target, target_len + 1);
    } else {
        /* Allocate data block for longer paths */
        uint64_t block;
        err = rinfs_block_alloc(mount, &block);
        if (err != RINFS_OK) {
            rinfs_inode_free(mount, link_ino);
            return err;
        }

        /* Write target to block */
        uint32_t block_size = mount->sb.s_block_size;
        uint8_t* buf = (uint8_t*)rinfs_malloc(block_size);
        if (!buf) {
            rinfs_block_free(mount, block);
            rinfs_inode_free(mount, link_ino);
            return RINFS_ERR_NOMEM;
        }

        rinfs_memset(buf, 0, block_size);
        rinfs_memcpy(buf, target, target_len + 1);
        err = rinfs_block_write_unprepared(mount, block, buf);
        rinfs_free(buf);

        if (err != RINFS_OK) {
            rinfs_block_free(mount, block);
            rinfs_inode_free(mount, link_ino);
            return err;
        }

        link_inode.i_block[0] = block;
        link_inode.i_blocks = block_size / 512;
    }

    /* Write symlink inode */
    err = rinfs_inode_write(mount, link_ino, &link_inode);
    if (err != RINFS_OK) {
        if (link_inode.i_block[0]) {
            rinfs_block_free(mount, link_inode.i_block[0]);
        }
        rinfs_inode_free(mount, link_ino);
        return err;
    }

    /* Add directory entry */
    err = rinfs_dirent_add(mount, dir_ino, name, link_ino, RINFS_FT_LNK);
    if (err != RINFS_OK) {
        if (link_inode.i_block[0]) {
            rinfs_block_free(mount, link_inode.i_block[0]);
        }
        rinfs_inode_free(mount, link_ino);
        return err;
    }

    return RINFS_OK;
}

int rinfs_symlink(RinFS_Mount* mount, uint64_t dir_ino, const char* name, const char* target) {
    return rinfs_symlink_owned(mount, dir_ino, name, target, 0, 0);
}

/* Read symbolic link target */
static int rinfs_readlink_unscoped(RinFS_Mount* mount, uint64_t ino,
                                   char* buf, uint32_t size) {
    if (!mount || !mount->mounted || !buf || size == 0) return RINFS_ERR_INVAL;

    /* Read inode */
    RinFS_Inode inode;
    int err = rinfs_inode_read(mount, ino, &inode);
    if (err != RINFS_OK) return err;

    /* Check it's a symlink */
    if ((inode.i_mode >> 12) != RINFS_FT_LNK) {
        return RINFS_ERR_INVAL;
    }

    uint32_t link_len = (uint32_t)inode.i_size;
    if (link_len == 0) return 0;

    /* Determine where target is stored */
    if (link_len < sizeof(inode.i_block)) {
        /* Fast symlink: target stored in i_block area */
        uint32_t copy_len = (link_len < size) ? link_len : size;
        rinfs_memcpy(buf, inode.i_block, copy_len);
        return (int)copy_len;
    } else {
        /* Target stored in data block */
        if (inode.i_block[0] == 0) {
            return RINFS_ERR_IO;
        }

        uint32_t block_size = mount->sb.s_block_size;
        uint8_t* data = (uint8_t*)rinfs_malloc(block_size);
        if (!data) return RINFS_ERR_NOMEM;

        err = rinfs_block_read(mount, inode.i_block[0], data);
        if (err != RINFS_OK) {
            rinfs_free(data);
            return err;
        }

        uint32_t copy_len = (link_len < size) ? link_len : size;
        rinfs_memcpy(buf, data, copy_len);
        rinfs_free(data);

        return (int)copy_len;
    }
}

/* Truncate file to specified size (by inode number) */
int rinfs_truncate_ino(RinFS_Mount* mount, uint64_t ino, uint64_t size) {
    int content_unlock_error = RINFS_OK;
    RinFS_ContentMutation mutation;
    RinFS_Inode* inode;
    uint32_t block_size;
    uint64_t old_size;
    int err;
    if (!mount || !mount->mounted) return rinfs_content_unlock_status((RINFS_ERR_INVAL), content_unlock_error);
    err = rinfs_mount_prepare_write(mount);
    if (err != RINFS_OK)
        return rinfs_content_unlock_status(
            err, content_unlock_error);
    block_size = mount->sb.s_block_size;

    err = rinfs_page_cache_sync(mount, ino, 0u, 0u, 0u, 0u, 0u);
    if (err != RINFS_OK)
        return rinfs_content_unlock_status((err == RINFS_ERR_PENDING ? RINFS_ERR_BUSY : err), content_unlock_error);
    err = rinfs_page_cache_invalidate_inode(mount, ino);
    if (err != RINFS_OK)
        return rinfs_content_unlock_status((err == RINFS_ERR_PENDING ? RINFS_ERR_BUSY : err), content_unlock_error);

    /* Refuse sizes that cannot be represented by the direct/indirect map. */
    if (size != 0) {
        uint64_t indices[3];
        uint32_t depth;
        int path_err = rinfs_file_block_path(mount, (size - 1) / block_size,
                                             &depth, indices);
        if (path_err != RINFS_OK) return rinfs_content_unlock_status((path_err), content_unlock_error);
    }

    err = rinfs_content_mutation_begin(mount, ino, RINFS_FT_REG,
                                       &mutation);
    if (err != RINFS_OK) return rinfs_content_unlock_status((err), content_unlock_error);
    inode = &mutation.inode;
    old_size = inode->i_size;

    if (size == old_size) {
        rinfs_keep_first_error(&content_unlock_error, rinfs_content_mutation_end(&mutation));
        return rinfs_content_unlock_status((RINFS_OK), content_unlock_error); /* Nothing to do */
    }
    err = rinfs_content_mutation_prepare(&mutation);
    if (err != RINFS_OK) {
        rinfs_keep_first_error(&content_unlock_error, rinfs_content_mutation_end(&mutation));
        return rinfs_content_unlock_status((err), content_unlock_error);
    }
    inode = &mutation.inode;
    if (rinfs_page_cache_invalidate_stale(
            mount, ino, inode->i_generation,
            rinfs_inode_content_version_raw(inode)) != RINFS_OK) {
        rinfs_content_mutation_started(&mutation);
        rinfs_content_mutation_poison(&mutation);
        rinfs_keep_first_error(&content_unlock_error, rinfs_content_mutation_end(&mutation));
        return rinfs_content_unlock_status((RINFS_ERR_PENDING), content_unlock_error);
    }
    rinfs_content_mutation_started(&mutation);

    if (size < old_size) {
        /* Clear the retained block's tail before shortening the inode, so a
         * later sparse extension cannot disclose bytes from the old file. */
        if ((size % block_size) != 0) {
            uint64_t phys_block = 0;
            err = get_file_block(mount, inode, size / block_size, &phys_block);
            if (err != RINFS_OK) goto failed;
            if (phys_block != 0) {
                uint8_t* block = (uint8_t*)rinfs_malloc(block_size);
                if (!block) {
                    err = RINFS_ERR_NOMEM;
                    goto failed;
                }
                err = rinfs_block_read(mount, phys_block, block);
                if (err == RINFS_OK) {
                    rinfs_memset(block + (size % block_size), 0,
                                 block_size - (size % block_size));
                    err = rinfs_block_write_unprepared(mount, phys_block, block);
                }
                rinfs_free(block);
                if (err != RINFS_OK) goto failed;
            }
        }

        uint64_t new_blocks = (size + block_size - 1) / block_size;
        inode->i_size = size;
        rinfs_touch_modified(inode);
        err = rinfs_inode_release_from(mount, ino, inode, new_blocks, 0);
        if (err != RINFS_OK) goto failed;
    } else {
        /* RinFS read already defines holes as zero.  Preserve that contract
         * instead of eagerly allocating every block during truncate. */
        if (old_size != 0 && (old_size % block_size) != 0) {
            uint64_t phys_block = 0;
            err = get_file_block(mount, inode, old_size / block_size, &phys_block);
            if (err != RINFS_OK) goto failed;
            if (phys_block != 0) {
                uint64_t zero_end = (old_size / block_size + 1) * block_size;
                if (zero_end > size) zero_end = size;
                uint8_t* block = (uint8_t*)rinfs_malloc(block_size);
                if (!block) {
                    err = RINFS_ERR_NOMEM;
                    goto failed;
                }
                err = rinfs_block_read(mount, phys_block, block);
                if (err == RINFS_OK) {
                    rinfs_memset(block + (old_size % block_size), 0,
                                 (uint32_t)(zero_end - old_size));
                    err = rinfs_block_write_unprepared(mount, phys_block, block);
                }
                rinfs_free(block);
                if (err != RINFS_OK) goto failed;
            }
        }
        inode->i_size = size;
        rinfs_touch_modified(inode);
        err = rinfs_inode_recount_blocks(mount, inode);
        if (err != RINFS_OK) goto failed;
        err = rinfs_inode_write_content(mount, ino, inode);
        if (err != RINFS_OK) goto failed;
    }

    err = rinfs_content_mutation_finalize(&mutation, inode);
    rinfs_keep_first_error(&content_unlock_error, rinfs_content_mutation_end(&mutation));
    return rinfs_content_unlock_status((err), content_unlock_error);

failed:
    rinfs_content_mutation_poison(&mutation);
    rinfs_keep_first_error(&content_unlock_error, rinfs_content_mutation_end(&mutation));
    return rinfs_content_unlock_status((err), content_unlock_error);
}

/* The restore record lives in the checksummed superblock padding. The
 * incompat feature makes old readers reject an in-progress restore, while
 * keeping the recovery phase independent of transaction-directory cleanup. */
#define RINFS_RESTORE_TX_MAGIC UINT32_C(0x31535452) /* RST1 */
#define RINFS_RESTORE_RECORD_MAGIC UINT32_C(0x31525452) /* RTR1 */
#define RINFS_RESTORE_VERSION 1u
#define RINFS_RESTORE_STAGE_NAME "stage"
#define RINFS_RESTORE_OLD_NAME "old"
#define RINFS_RESTORE_MAP_NAME "map"
#define RINFS_RESTORE_METADATA_NAME "metadata"
#define RINFS_RESTORE_PHASE_RECEIVING 1u
#define RINFS_RESTORE_PHASE_MOVING_OLD 2u
#define RINFS_RESTORE_PHASE_INSTALLING 3u
#define RINFS_RESTORE_PHASE_CLEANING 4u
#define RINFS_RESTORE_PHASE_DONE 5u
#define RINFS_RESTORE_PHASE_ABORTING 6u
#define RINFS_RESTORE_PERSISTENT_FLAGS \
    (RINFS_IFLG_SYNC | RINFS_IFLG_IMMUT | RINFS_IFLG_APPEND | \
     RINFS_IFLG_NODUMP)

typedef struct {
    uint32_t magic;
    uint32_t version;
    uint32_t phase;
    uint32_t checksum;
    uint64_t transaction_inode;
    uint64_t staging_inode;
    uint64_t old_inode;
    uint64_t map_inode;
    uint64_t metadata_inode;
    uint64_t map_entries;
    uint64_t metadata_entries;
    uint32_t root_metadata_valid;
    uint32_t root_uid;
    uint32_t root_gid;
    uint16_t root_mode;
    uint16_t root_flags;
    RinFS_InodeTimes root_times;
    int64_t root_change_time_seconds;
} RinFS_RestoreRecord;

typedef struct {
    uint32_t magic;
    uint32_t checksum;
    uint64_t inode_number;
    uint32_t inode_generation;
    uint32_t reserved;
    uint16_t mode;
    uint16_t persistent_flags;
    uint32_t uid;
    uint32_t gid;
    RinFS_InodeTimes times;
    int64_t change_time_seconds;
} RinFS_RestoreMetadataRecord;

typedef struct {
    uint32_t magic;
    RinFS_Mount* mount;
    uint64_t mount_epoch;
    RinFS_RestoreRecord record;
} RinFS_RestoreTransactionInternal;

#define RINFS_MAX_RESTORE_TRANSACTION_HANDLES 32u
#define RINFS_MAX_RESTORE_MOUNT_GATES 32u
#define RINFS_RESTORE_HANDLE_RESERVED 1u
#define RINFS_RESTORE_HANDLE_ACTIVE 2u

typedef struct {
    uint32_t state;
    uint32_t token;
    uint32_t operation_active;
    uint32_t reserved;
    RinFS_RestoreTransactionV1* handle;
    void* internal;
    RinFS_Mount* mount;
    uint64_t mount_epoch;
} RinFS_RestoreTransactionHandleRecord;

typedef struct {
    RinFS_Mount* mount;
    uint64_t mount_epoch;
    uint32_t transaction_references;
    uint32_t teardown_active;
    uint32_t shared_owner_row;
    uint32_t reserved;
    uint64_t shared_owner_cookie;
} RinFS_RestoreMountGateRecord;

typedef struct {
    uint32_t slot;
    uint32_t token;
    uint32_t shared_owner_row;
    uint32_t reserved;
    uint64_t shared_owner_cookie;
    RinFS_RestoreTransactionV1* handle;
    RinFS_RestoreTransactionInternal* internal;
    uint32_t active;
    RinFS_RestoreInternalScope internal_scope;
} RinFS_RestoreTransactionOperation;

static volatile uint32_t g_rinfs_restore_transaction_lock;
static RinFS_RestoreTransactionHandleRecord
    g_rinfs_restore_transaction_handles[RINFS_MAX_RESTORE_TRANSACTION_HANDLES];
static RinFS_RestoreMountGateRecord
    g_rinfs_restore_mount_gates[RINFS_MAX_RESTORE_MOUNT_GATES];
static uint32_t g_rinfs_restore_transaction_next_token = 1u;

static RinFS_RestoreMountGateRecord* rinfs_restore_mount_gate_find_locked(
    RinFS_Mount* mount) {
    for (uint32_t index = 0u; index < RINFS_MAX_RESTORE_MOUNT_GATES; ++index) {
        if (g_rinfs_restore_mount_gates[index].mount == mount)
            return &g_rinfs_restore_mount_gates[index];
    }
    return NULL;
}

static RinFS_RestoreTransactionHandleRecord*
rinfs_restore_transaction_handle_find_locked(uint32_t token) {
    for (uint32_t index = 0u;
         index < RINFS_MAX_RESTORE_TRANSACTION_HANDLES; ++index) {
        RinFS_RestoreTransactionHandleRecord* record =
            &g_rinfs_restore_transaction_handles[index];
        if (record->state != 0u && record->token == token) return record;
    }
    return NULL;
}

static int rinfs_restore_transaction_operation_end(
    RinFS_RestoreTransactionOperation* operation, int retire);
static void rinfs_restore_internal_destroy(
    RinFS_RestoreTransactionInternal* internal);

static int rinfs_restore_transaction_registry_audit_locked(void) {
    uint32_t handle_count[RINFS_MAX_RESTORE_MOUNT_GATES] = {0u};
    for (uint32_t index = 0u;
         index < RINFS_MAX_RESTORE_TRANSACTION_HANDLES; ++index) {
        const RinFS_RestoreTransactionHandleRecord* record =
            &g_rinfs_restore_transaction_handles[index];
        if (record->state == 0u) {
            if (record->token != 0u || record->operation_active != 0u ||
                record->reserved != 0u || record->handle || record->internal ||
                record->mount || record->mount_epoch != 0u)
                return 0;
            continue;
        }
        if ((record->state != RINFS_RESTORE_HANDLE_RESERVED &&
             record->state != RINFS_RESTORE_HANDLE_ACTIVE) ||
            record->token == 0u || record->reserved != 0u ||
            record->operation_active > 1u || !record->handle ||
            !record->mount || record->mount_epoch == 0u ||
            (record->state == RINFS_RESTORE_HANDLE_RESERVED &&
             (record->internal || record->operation_active != 0u)) ||
            (record->state == RINFS_RESTORE_HANDLE_ACTIVE &&
             !record->internal))
            return 0;
        int gate_found = 0;
        for (uint32_t gate_index = 0u;
             gate_index < RINFS_MAX_RESTORE_MOUNT_GATES; ++gate_index) {
            const RinFS_RestoreMountGateRecord* gate =
                &g_rinfs_restore_mount_gates[gate_index];
            if (gate->mount == record->mount &&
                gate->mount_epoch == record->mount_epoch) {
                ++handle_count[gate_index];
                gate_found = 1;
                break;
            }
        }
        if (!gate_found) return 0;
    }
    for (uint32_t index = 0u; index < RINFS_MAX_RESTORE_MOUNT_GATES; ++index) {
        const RinFS_RestoreMountGateRecord* gate =
            &g_rinfs_restore_mount_gates[index];
        if (!gate->mount) {
            if (gate->mount_epoch != 0u ||
                gate->transaction_references != 0u ||
                gate->teardown_active != 0u ||
                gate->shared_owner_row != 0u || gate->reserved != 0u ||
                gate->shared_owner_cookie != 0u ||
                handle_count[index] != 0u)
                return 0;
            continue;
        }
        if (gate->mount_epoch == 0u || gate->teardown_active > 1u ||
            gate->reserved != 0u ||
            ((gate->shared_owner_row == 0u) !=
             (gate->shared_owner_cookie == 0u)) ||
            gate->shared_owner_row > RINFS_SHARED_OWNER_CAPACITY ||
            (gate->transaction_references == 0u &&
             gate->teardown_active == 0u &&
             (gate->shared_owner_row != 0u ||
              gate->shared_owner_cookie != 0u)) ||
            (gate->transaction_references != 0u &&
             gate->mount->shared_mapping_base &&
             (gate->shared_owner_row == 0u ||
              gate->shared_owner_cookie == 0u)) ||
            gate->transaction_references != handle_count[index] ||
            (gate->transaction_references == 0u &&
             gate->teardown_active == 0u))
            return 0;
    }
    return 1;
}

static int rinfs_restore_mount_has_live_content(RinFS_Mount* mount) {
    RinFS_ContentLeaseNode* node;
    uint64_t visited = 0u;
    if (!mount) return RINFS_ERR_INVAL;
    node = (RinFS_ContentLeaseNode*)mount->content_leases;
    while (node) {
        if (++visited > mount->sb.s_inode_count)
            return RINFS_ERR_CORRUPT;
        if (node->references != 0u || node->readers != 0u ||
            node->waiting_writers != 0u || node->writer != 0u ||
            node->open_references != 0u ||
            node->tracked_open_references != 0u ||
            node->wincompat_share_handle_count != 0u ||
            node->delete_pending != 0u ||
            node->delete_on_close_count != 0u ||
            node->delete_on_close_paths != NULL)
            return RINFS_ERR_BUSY;
        node = node->next;
    }
    return RINFS_OK;
}

/* A restore replaces namespace and inode contents while it owns the mount.
 * New transactions and recovery may retain validated dirty pages only long
 * enough to sync them under the gate. Referenced or transitional entries are
 * never admitted, and clean unreferenced entries are discarded so old cache
 * contents cannot survive the restore boundary. */
static int rinfs_restore_page_cache_quiesce(RinFS_Mount* mount,
                                           int allow_dirty_pages) {
    RinFS_PageCache* cache;
    uint64_t dirty_pages = 0u;
    uint64_t dirty_bytes = 0u;
    int result;
    if (!mount || (allow_dirty_pages != 0 && allow_dirty_pages != 1))
        return RINFS_ERR_INVAL;
    if (!allow_dirty_pages && mount->buffer_dirty) return RINFS_ERR_BUSY;
    cache = mount->page_cache;
    if (!cache) return RINFS_OK;
    result = rinfs_page_cache_lock(cache);
    if (result != RINFS_OK) return result;
    for (uint32_t index = 0u; index < RINFS_PAGE_CACHE_CAPACITY; ++index) {
        const RinFS_PageCacheEntry* entry = &cache->entries[index];
        if (entry->references != 0u) {
            return rinfs_page_cache_unlock_status(cache, RINFS_ERR_BUSY);
        }
        if (!entry->valid || entry->state == RINFS_PAGE_CACHE_CLEAN)
            continue;
        if (!allow_dirty_pages || entry->state != RINFS_PAGE_CACHE_DIRTY)
            return rinfs_page_cache_unlock_status(cache, RINFS_ERR_BUSY);
        if (entry->dirty_end <= entry->dirty_start ||
            entry->dirty_end > mount->sb.s_block_size)
            return rinfs_page_cache_unlock_status(cache, RINFS_ERR_CORRUPT);
        ++dirty_pages;
        dirty_bytes += entry->dirty_end - entry->dirty_start;
    }
    if (cache->dirty_pages != dirty_pages ||
        cache->dirty_bytes != dirty_bytes)
        return rinfs_page_cache_unlock_status(cache, RINFS_ERR_CORRUPT);
    for (uint32_t index = 0u; index < RINFS_PAGE_CACHE_CAPACITY; ++index) {
        RinFS_PageCacheEntry* entry = &cache->entries[index];
        if (entry->valid && entry->state == RINFS_PAGE_CACHE_CLEAN) {
            rinfs_page_cache_discard_locked(cache, entry);
            ++cache->evictions;
        }
    }
    return rinfs_page_cache_unlock_status(cache, RINFS_OK);
}

/* Recovery sync is idempotent while the pending restore record remains
 * authoritative. Retry transient storage and allocation failures a bounded
 * number of times before the caller fences the mount read-only. */
static int rinfs_restore_cache_sync_for_recovery(RinFS_Mount* mount) {
    int error = RINFS_OK;
    for (uint32_t attempt = 0u; attempt < 3u; ++attempt) {
        error = rinfs_sync(mount);
        if (error != RINFS_ERR_IO && error != RINFS_ERR_NOMEM)
            return error;
    }
    return error;
}

/* Bind restore admission and ordinary-operation exclusion under the same
 * recoverable content lock. Shared mounts additionally retain the exact
 * kernel-issued owner row/cookie so a reaped process cannot strand or release
 * a later owner's transaction gate. */
static int rinfs_restore_shared_gate_claim(
    RinFS_Mount* mount, uint64_t mount_epoch, uint32_t* owner_row_out,
    uint64_t* owner_cookie_out, int allow_dirty_pages,
    int allow_recovery_readonly) {
    RinFS_SharedOwnerV1* owner;
    uint32_t owner_row = 0u;
    uint32_t gate_row;
    uint64_t owner_cookie;
    uint64_t process_id;
    RinFS_RestoreInternalScope cache_scope = {0u};
    int shared_mount;
    int result = RINFS_OK;
    int unlock_error;
    if (owner_row_out) *owner_row_out = 0u;
    if (owner_cookie_out) *owner_cookie_out = 0u;
    if (!mount || mount_epoch == 0u || !owner_row_out ||
        (allow_dirty_pages != 0 && allow_dirty_pages != 1) ||
        (allow_recovery_readonly != 0 && allow_recovery_readonly != 1) ||
        !owner_cookie_out)
        return RINFS_ERR_INVAL;
    shared_mount = mount->shared_mapping_base != NULL;
    if (shared_mount &&
        (mount->shared_mount_ready == 0u ||
         !rinfs_shared_owner_ledger_valid(mount) ||
         rinfs_shared_owner_query_row(mount, &owner_row) != RINFS_OK ||
         owner_row == 0u || owner_row > RINFS_SHARED_OWNER_CAPACITY))
        return RINFS_ERR_BUSY;
    process_id = rinfs_restore_current_process_id();
    if (process_id == 0u) return RINFS_ERR_BUSY;
    result = rinfs_shared_content_lock(mount);
    if (result != RINFS_OK) return result;
    owner = shared_mount
                ? &mount->shared_owner_ledger->owners[owner_row - 1u]
                : NULL;
    owner_cookie = owner ? owner->owner_cookie : 0u;
    if (!mount->mounted || mount->mount_epoch != mount_epoch ||
        (owner && (__atomic_load_n(&owner->state, __ATOMIC_ACQUIRE) !=
                       RINFS_SHARED_OWNER_ACTIVE || owner_cookie == 0u))) {
        result = RINFS_ERR_STALE;
        goto done;
    }
    if (mount->readonly &&
        (!allow_recovery_readonly || !rinfs_mount_recovery_only(mount) ||
         (rinfs_mount_readonly_state(mount) &
          RINFS_READONLY_RECOVERY_RESTORE_MASK) == 0u)) {
        result = RINFS_ERR_ROFS;
        goto done;
    }
    gate_row = __atomic_load_n(&mount->restore_transaction_owner_row,
                               __ATOMIC_ACQUIRE);
    if (mount->restore_transaction_reserved != 0u ||
        mount->restore_operation_reserved != 0u ||
        mount->restore_operation_count_reserved != 0u ||
        gate_row > RINFS_SHARED_OWNER_CAPACITY) {
        result = RINFS_ERR_CORRUPT;
        goto done;
    }
    if (shared_mount) {
        uint32_t operation_gate = __atomic_load_n(
            &mount->restore_operation_gate_active, __ATOMIC_ACQUIRE);
        if (((gate_row == 0u) !=
             (mount->restore_transaction_owner_cookie == 0u)) ||
            ((gate_row == 0u) !=
             (mount->restore_transaction_mount_epoch == 0u)) ||
            ((gate_row == 0u) != (operation_gate == 0u)) ||
            ((gate_row == 0u) !=
             (mount->restore_operation_owner_process_id == 0u))) {
            result = RINFS_ERR_CORRUPT;
            goto done;
        }
    } else {
        if (gate_row != 0u ||
            mount->restore_transaction_owner_cookie != 0u ||
            mount->restore_transaction_mount_epoch != 0u) {
            result = RINFS_ERR_CORRUPT;
            goto done;
        }
        if (__atomic_load_n(&mount->restore_operation_gate_active,
                            __ATOMIC_ACQUIRE) != 0u ||
            mount->restore_operation_owner_process_id != 0u) {
            result = RINFS_ERR_PENDING;
            goto done;
        }
    }
    if (shared_mount && gate_row != 0u) {
        RinFS_SharedOwnerV1* gate_owner =
            &mount->shared_owner_ledger->owners[gate_row - 1u];
        uint32_t gate_owner_state = __atomic_load_n(
            &gate_owner->state, __ATOMIC_ACQUIRE);
        uint64_t stale_cookie =
            mount->restore_transaction_owner_cookie;
        uint64_t stale_epoch =
            mount->restore_transaction_mount_epoch;
        if (stale_cookie == 0u || stale_epoch == 0u) {
            result = RINFS_ERR_CORRUPT;
            goto done;
        }
        if (gate_owner_state == RINFS_SHARED_OWNER_ACTIVE) {
            if (gate_owner->owner_cookie == stale_cookie) {
                result = stale_epoch == mount_epoch
                             ? RINFS_ERR_PENDING : RINFS_ERR_CORRUPT;
                goto done;
            }
            /* The kernel reuses a row only after publishing the previous
             * owner as REAPED. A new active cookie therefore proves that the
             * transaction owner which installed this gate has exited. */
            if (gate_owner->owner_cookie == 0u) {
                result = RINFS_ERR_CORRUPT;
                goto done;
            }
        } else if (gate_owner_state == RINFS_SHARED_OWNER_DEAD) {
            if (gate_owner->owner_cookie != stale_cookie) {
                result = RINFS_ERR_CORRUPT;
                goto done;
            }
        } else if (gate_owner_state == RINFS_SHARED_OWNER_REAPED) {
            /* REAPED rows can be in the middle of kernel reassignment, so a
             * different nonzero cookie is also safe to retire here. */
            if (gate_owner->owner_cookie == 0u) {
                result = RINFS_ERR_CORRUPT;
                goto done;
            }
        } else {
            /* FREE has no owner-death proof and must never release a gate. */
            result = RINFS_ERR_CORRUPT;
            goto done;
        }
        mount->restore_transaction_owner_cookie = 0u;
        mount->restore_transaction_mount_epoch = 0u;
        __atomic_store_n(&mount->restore_transaction_owner_row, 0u,
                         __ATOMIC_RELEASE);
        __atomic_store_n(&mount->restore_operation_gate_active, 0u,
                         __ATOMIC_RELEASE);
        __atomic_store_n(&mount->restore_operation_owner_process_id, 0u,
                         __ATOMIC_RELEASE);
    } else if (gate_row != 0u) {
        result = RINFS_ERR_CORRUPT;
        goto done;
    }
    result = rinfs_restore_mount_has_live_content(mount);
    if (result != RINFS_OK) goto done;
    result = rinfs_restore_operation_count_reconcile_locked(mount);
    if (result != RINFS_OK) goto done;
    if (mount->restore_operation_active_count != 0u) {
        result = RINFS_ERR_BUSY;
        goto done;
    }
    if (shared_mount) {
        mount->restore_transaction_owner_cookie = owner_cookie;
        mount->restore_transaction_mount_epoch = mount_epoch;
        __atomic_store_n(&mount->restore_transaction_owner_row, owner_row,
                         __ATOMIC_RELEASE);
    }
    mount->restore_operation_reserved = 0u;
    __atomic_store_n(&mount->restore_operation_owner_process_id, process_id,
                     __ATOMIC_RELAXED);
    __atomic_store_n(&mount->restore_operation_gate_active, 1u,
                     __ATOMIC_RELEASE);
    result = rinfs_restore_internal_scope_enter(&cache_scope);
    if (result == RINFS_OK)
        result = rinfs_restore_page_cache_quiesce(
            mount, allow_dirty_pages);
    rinfs_restore_internal_scope_leave(&cache_scope);
    if (result != RINFS_OK) {
        if (shared_mount) {
            mount->restore_transaction_owner_cookie = 0u;
            mount->restore_transaction_mount_epoch = 0u;
            __atomic_store_n(&mount->restore_transaction_owner_row, 0u,
                             __ATOMIC_RELEASE);
        }
        __atomic_store_n(&mount->restore_operation_gate_active, 0u,
                         __ATOMIC_RELEASE);
        __atomic_store_n(&mount->restore_operation_owner_process_id, 0u,
                         __ATOMIC_RELEASE);
        goto done;
    }
    *owner_row_out = owner_row;
    *owner_cookie_out = owner_cookie;
done:
    unlock_error = rinfs_shared_content_unlock(mount);
    if (unlock_error != RINFS_OK) {
        rinfs_mount_force_readonly(mount);
        result = unlock_error;
        *owner_row_out = 0u;
        *owner_cookie_out = 0u;
    }
    if (result == RINFS_ERR_CORRUPT) {
        rinfs_mount_force_readonly(mount);
        mount->content_lease_closing = UINT32_MAX;
    }
    return result;
}

static int rinfs_restore_shared_gate_owner_check(
    RinFS_Mount* mount, uint32_t expected_row, uint64_t expected_cookie) {
    RinFS_SharedOwnerV1* owner;
    uint32_t current_row = 0u;
    if (!mount) return RINFS_ERR_INVAL;
    if (!mount->shared_mapping_base)
        return expected_row == 0u && expected_cookie == 0u
                   ? RINFS_OK : RINFS_ERR_CORRUPT;
    if (expected_row == 0u ||
        expected_row > RINFS_SHARED_OWNER_CAPACITY ||
        expected_cookie == 0u ||
        !rinfs_shared_owner_ledger_valid(mount))
        return RINFS_ERR_CORRUPT;
    if (mount->shared_mount_ready == 0u) return RINFS_ERR_BUSY;
    if (rinfs_shared_owner_query_row(mount, &current_row) != RINFS_OK)
        return RINFS_ERR_BUSY;
    if (current_row != expected_row) return RINFS_ERR_STALE;
    owner = &mount->shared_owner_ledger->owners[current_row - 1u];
    if (__atomic_load_n(&owner->state, __ATOMIC_ACQUIRE) !=
            RINFS_SHARED_OWNER_ACTIVE ||
        owner->owner_cookie != expected_cookie)
        return RINFS_ERR_STALE;
    return RINFS_OK;
}

static int rinfs_restore_shared_gate_release(
    RinFS_Mount* mount, uint64_t mount_epoch, uint32_t owner_row,
    uint64_t owner_cookie) {
    uint32_t gate_row;
    int result;
    int unlock_error;
    if (!mount) return RINFS_ERR_INVAL;
    if (!mount->shared_mapping_base) {
        if (owner_row != 0u || owner_cookie != 0u || mount_epoch == 0u)
            return RINFS_ERR_CORRUPT;
        result = rinfs_shared_content_lock(mount);
        if (result != RINFS_OK) return result;
        if (__atomic_load_n(&mount->restore_operation_gate_active,
                            __ATOMIC_ACQUIRE) != 1u ||
            mount->restore_operation_reserved != 0u ||
            mount->restore_operation_count_reserved != 0u ||
            mount->restore_operation_owner_process_id !=
                rinfs_restore_current_process_id() ||
            mount->restore_operation_owner_process_id == 0u) {
            result = RINFS_ERR_STALE;
        } else {
            __atomic_store_n(&mount->restore_operation_gate_active, 0u,
                             __ATOMIC_RELEASE);
            __atomic_store_n(&mount->restore_operation_owner_process_id, 0u,
                             __ATOMIC_RELEASE);
            result = RINFS_OK;
        }
        unlock_error = rinfs_shared_content_unlock(mount);
        if (unlock_error != RINFS_OK) {
            rinfs_mount_force_readonly(mount);
            return unlock_error;
        }
        return result;
    }
    if (mount_epoch == 0u || owner_row == 0u ||
        owner_row > RINFS_SHARED_OWNER_CAPACITY || owner_cookie == 0u)
        return RINFS_ERR_INVAL;
    result = rinfs_shared_content_lock(mount);
    if (result != RINFS_OK) return result;
    result = rinfs_restore_shared_gate_owner_check(
        mount, owner_row, owner_cookie);
    if (result != RINFS_OK) {
        unlock_error = rinfs_shared_content_unlock(mount);
        if (unlock_error != RINFS_OK) {
            rinfs_mount_force_readonly(mount);
            return unlock_error;
        }
        return result;
    }
    gate_row = __atomic_load_n(&mount->restore_transaction_owner_row,
                               __ATOMIC_ACQUIRE);
    if (gate_row != owner_row ||
        mount->restore_transaction_owner_cookie != owner_cookie ||
        mount->restore_transaction_mount_epoch != mount_epoch ||
        mount->restore_transaction_reserved != 0u ||
        mount->restore_operation_reserved != 0u ||
        mount->restore_operation_count_reserved != 0u ||
        __atomic_load_n(&mount->restore_operation_gate_active,
                        __ATOMIC_ACQUIRE) != 1u ||
        mount->restore_operation_owner_process_id !=
            rinfs_restore_current_process_id() ||
        mount->restore_operation_owner_process_id == 0u) {
        result = RINFS_ERR_CORRUPT;
    } else {
        mount->restore_transaction_owner_cookie = 0u;
        mount->restore_transaction_mount_epoch = 0u;
        __atomic_store_n(&mount->restore_transaction_owner_row, 0u,
                         __ATOMIC_RELEASE);
        __atomic_store_n(&mount->restore_operation_gate_active, 0u,
                         __ATOMIC_RELEASE);
        __atomic_store_n(&mount->restore_operation_owner_process_id, 0u,
                         __ATOMIC_RELEASE);
        result = RINFS_OK;
    }
    unlock_error = rinfs_shared_content_unlock(mount);
    if (unlock_error != RINFS_OK) {
        rinfs_mount_force_readonly(mount);
        result = unlock_error;
    }
    if (result == RINFS_ERR_CORRUPT) {
        rinfs_mount_force_readonly(mount);
        mount->content_lease_closing = UINT32_MAX;
    }
    return result;
}

static int rinfs_restore_transaction_reserve(
    RinFS_Mount* mount, uint64_t mount_epoch,
    RinFS_RestoreTransactionV1* handle, uint32_t* token_out) {
    RinFS_RestoreMountGateRecord* gate;
    RinFS_RestoreTransactionHandleRecord* free_record = NULL;
    uint32_t free_gate = RINFS_MAX_RESTORE_MOUNT_GATES;
    uint32_t token;
    uint32_t shared_owner_row = 0u;
    uint64_t shared_owner_cookie = 0u;
    int shared_gate_error;
    if (token_out) *token_out = 0u;
    if (!mount || mount_epoch == 0u || !handle || !token_out)
        return RINFS_ERR_INVAL;
    rinfs_spin_lock(&g_rinfs_restore_transaction_lock);
    if (!rinfs_restore_transaction_registry_audit_locked()) {
        rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
        return RINFS_ERR_CORRUPT;
    }
    if (handle->magic != 0u || handle->reserved != 0u || handle->internal) {
        rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
        return RINFS_ERR_STALE;
    }
    gate = rinfs_restore_mount_gate_find_locked(mount);
    if (gate && (gate->mount_epoch != mount_epoch ||
                 gate->teardown_active != 0u ||
                 gate->transaction_references != 0u)) {
        rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
        return RINFS_ERR_PENDING;
    }
    if (!mount->mounted || mount->mount_epoch != mount_epoch) {
        rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
        return RINFS_ERR_STALE;
    }
    if (mount->readonly) {
        rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
        return RINFS_ERR_ROFS;
    }
    if (g_rinfs_restore_transaction_next_token == 0u ||
        g_rinfs_restore_transaction_next_token == UINT32_MAX) {
        rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
        return RINFS_ERR_OVERFLOW;
    }
    for (uint32_t index = 0u;
         index < RINFS_MAX_RESTORE_TRANSACTION_HANDLES; ++index) {
        RinFS_RestoreTransactionHandleRecord* record =
            &g_rinfs_restore_transaction_handles[index];
        if (record->state != 0u && record->handle == handle) {
            rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
            return RINFS_ERR_PENDING;
        }
        if (record->state == 0u) {
            free_record = &g_rinfs_restore_transaction_handles[index];
            break;
        }
    }
    if (!gate) {
        for (uint32_t index = 0u;
             index < RINFS_MAX_RESTORE_MOUNT_GATES; ++index) {
            if (!g_rinfs_restore_mount_gates[index].mount) {
                free_gate = index;
                break;
            }
        }
    }
    if (!free_record || (!gate && free_gate == RINFS_MAX_RESTORE_MOUNT_GATES)) {
        rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
        return RINFS_ERR_NOSPC;
    }
    shared_gate_error = rinfs_restore_shared_gate_claim(
        mount, mount_epoch, &shared_owner_row, &shared_owner_cookie, 1, 0);
    if (shared_gate_error != RINFS_OK) {
        rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
        return shared_gate_error;
    }
    if (!gate) {
        gate = &g_rinfs_restore_mount_gates[free_gate];
        gate->mount = mount;
        gate->mount_epoch = mount_epoch;
        gate->shared_owner_row = shared_owner_row;
        gate->shared_owner_cookie = shared_owner_cookie;
    }
    token = g_rinfs_restore_transaction_next_token++;
    free_record->state = RINFS_RESTORE_HANDLE_RESERVED;
    free_record->token = token;
    free_record->handle = handle;
    free_record->mount = mount;
    free_record->mount_epoch = mount_epoch;
    ++gate->transaction_references;
    *token_out = token;
    rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
    return RINFS_OK;
}

static int rinfs_restore_transaction_publish(
    RinFS_RestoreTransactionV1* handle,
    RinFS_RestoreTransactionInternal* internal, uint32_t token) {
    RinFS_RestoreTransactionHandleRecord* record;
    if (!handle || !internal || token == 0u) return RINFS_ERR_INVAL;
    rinfs_spin_lock(&g_rinfs_restore_transaction_lock);
    if (!rinfs_restore_transaction_registry_audit_locked()) {
        rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
        return RINFS_ERR_CORRUPT;
    }
    record = rinfs_restore_transaction_handle_find_locked(token);
    if (!record || record->state != RINFS_RESTORE_HANDLE_RESERVED ||
        record->handle != handle || record->mount != internal->mount ||
        record->mount_epoch != internal->mount_epoch ||
        handle->magic != 0u || handle->reserved != 0u || handle->internal) {
        rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
        return RINFS_ERR_STALE;
    }
    handle->magic = RINFS_RESTORE_TX_MAGIC;
    handle->reserved = token;
    handle->internal = internal;
    record->internal = internal;
    record->state = RINFS_RESTORE_HANDLE_ACTIVE;
    rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
    return RINFS_OK;
}

static int rinfs_restore_transaction_reservation_abort(
    RinFS_RestoreTransactionV1* handle, uint32_t token) {
    RinFS_RestoreTransactionHandleRecord* record;
    RinFS_RestoreMountGateRecord* gate;
    if (!handle || token == 0u) return RINFS_ERR_INVAL;
    rinfs_spin_lock(&g_rinfs_restore_transaction_lock);
    if (!rinfs_restore_transaction_registry_audit_locked()) {
        rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
        return RINFS_ERR_CORRUPT;
    }
    record = rinfs_restore_transaction_handle_find_locked(token);
    if (!record || record->state != RINFS_RESTORE_HANDLE_RESERVED ||
        record->handle != handle) {
        rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
        return RINFS_ERR_STALE;
    }
    gate = rinfs_restore_mount_gate_find_locked(record->mount);
    if (!gate || gate->mount_epoch != record->mount_epoch ||
        gate->transaction_references == 0u) {
        rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
        return RINFS_ERR_CORRUPT;
    }
    {
        int release_error = rinfs_restore_shared_gate_release(
            record->mount, record->mount_epoch, gate->shared_owner_row,
            gate->shared_owner_cookie);
        if (release_error != RINFS_OK) {
            rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
            return release_error;
        }
    }
    --gate->transaction_references;
    rinfs_memset(record, 0, sizeof(*record));
    if (gate->transaction_references == 0u && gate->teardown_active == 0u)
        rinfs_memset(gate, 0, sizeof(*gate));
    rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
    return RINFS_OK;
}

static int rinfs_restore_transaction_operation_begin(
    RinFS_RestoreTransactionV1* handle, int allow_stale_mount,
    RinFS_RestoreTransactionOperation* operation,
    RinFS_RestoreTransactionInternal** internal_out) {
    RinFS_RestoreTransactionHandleRecord* record;
    RinFS_RestoreMountGateRecord* gate;
    RinFS_RestoreTransactionInternal* internal;
    uint32_t token;
    void* public_internal;
    if (operation) rinfs_memset(operation, 0, sizeof(*operation));
    if (internal_out) *internal_out = NULL;
    if (!handle || !operation || !internal_out)
        return RINFS_ERR_INVAL;
    rinfs_spin_lock(&g_rinfs_restore_transaction_lock);
    if (!rinfs_restore_transaction_registry_audit_locked()) {
        rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
        return RINFS_ERR_CORRUPT;
    }
    record = NULL;
    for (uint32_t index = 0u;
         index < RINFS_MAX_RESTORE_TRANSACTION_HANDLES; ++index) {
        if (g_rinfs_restore_transaction_handles[index].handle == handle &&
            g_rinfs_restore_transaction_handles[index].state != 0u) {
            record = &g_rinfs_restore_transaction_handles[index];
            break;
        }
    }
    if (!record) {
        rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
        return RINFS_ERR_STALE;
    }
    if (record->state == RINFS_RESTORE_HANDLE_RESERVED ||
        record->operation_active != 0u) {
        rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
        return RINFS_ERR_PENDING;
    }
    token = handle->reserved;
    public_internal = handle->internal;
    if (record->state != RINFS_RESTORE_HANDLE_ACTIVE ||
        handle->magic != RINFS_RESTORE_TX_MAGIC || token != record->token ||
        public_internal != record->internal) {
        rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
        return RINFS_ERR_STALE;
    }
    gate = rinfs_restore_mount_gate_find_locked(record->mount);
    if (!gate || gate->mount_epoch != record->mount_epoch ||
        gate->transaction_references == 0u) {
        rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
        return RINFS_ERR_CORRUPT;
    }
    record->operation_active = 1u;
    operation->slot = (uint32_t)(record -
        g_rinfs_restore_transaction_handles);
    operation->token = token;
    operation->shared_owner_row = gate->shared_owner_row;
    operation->shared_owner_cookie = gate->shared_owner_cookie;
    operation->handle = handle;
    operation->internal =
        (RinFS_RestoreTransactionInternal*)record->internal;
    operation->active = 1u;
    rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);

    internal = operation->internal;
    if (internal->magic != RINFS_RESTORE_TX_MAGIC ||
        internal->mount == NULL || internal->mount_epoch == 0u) {
        int release_error = rinfs_restore_transaction_operation_end(
            operation, 0);
        return release_error == RINFS_OK ? RINFS_ERR_CORRUPT
                                         : release_error;
    }
    {
        int owner_error = rinfs_restore_shared_gate_owner_check(
            internal->mount, operation->shared_owner_row,
            operation->shared_owner_cookie);
        if (owner_error != RINFS_OK) {
            int release_error = rinfs_restore_transaction_operation_end(
                operation, 0);
            return release_error == RINFS_OK ? owner_error : release_error;
        }
    }
    if (!allow_stale_mount &&
        (internal->mount->mount_epoch != internal->mount_epoch ||
         !internal->mount->mounted)) {
        int release_error = rinfs_restore_transaction_operation_end(
            operation, 0);
        return release_error == RINFS_OK ? RINFS_ERR_STALE : release_error;
    }
    {
        int scope_error = rinfs_restore_internal_scope_enter(
            &operation->internal_scope);
        if (scope_error != RINFS_OK) {
            int release_error = rinfs_restore_transaction_operation_end(
                operation, 0);
            return release_error == RINFS_OK ? scope_error : release_error;
        }
    }
    if (!allow_stale_mount) {
        int prepare_error = rinfs_mount_prepare_write(internal->mount);
        if (prepare_error != RINFS_OK) {
            int release_error = rinfs_restore_transaction_operation_end(
                operation, 0);
            return release_error == RINFS_OK ? prepare_error : release_error;
        }
    }
    *internal_out = internal;
    return RINFS_OK;
}

static int rinfs_restore_transaction_operation_end(
    RinFS_RestoreTransactionOperation* operation, int retire) {
    RinFS_RestoreTransactionHandleRecord* record;
    RinFS_RestoreMountGateRecord* gate;
    RinFS_RestoreTransactionInternal* retired_internal = NULL;
    int result = RINFS_ERR_CORRUPT;
    if (!operation || operation->active != 1u ||
        operation->slot >= RINFS_MAX_RESTORE_TRANSACTION_HANDLES ||
        operation->token == 0u || !operation->handle ||
        !operation->internal)
        return RINFS_ERR_INVAL;
    rinfs_spin_lock(&g_rinfs_restore_transaction_lock);
    if (rinfs_restore_transaction_registry_audit_locked()) {
        record = &g_rinfs_restore_transaction_handles[operation->slot];
        if (record->state == RINFS_RESTORE_HANDLE_ACTIVE &&
            record->token == operation->token &&
            record->handle == operation->handle &&
            record->internal == operation->internal &&
            record->operation_active == 1u) {
            if (retire) {
                gate = rinfs_restore_mount_gate_find_locked(record->mount);
                if (!gate || gate->mount_epoch != record->mount_epoch ||
                    gate->transaction_references == 0u) {
                    result = RINFS_ERR_CORRUPT;
                } else {
                    int release_error = rinfs_restore_shared_gate_release(
                        record->mount, record->mount_epoch,
                        gate->shared_owner_row,
                        gate->shared_owner_cookie);
                    if (release_error != RINFS_OK) {
                        /* Keep the public handle and internal object alive so
                         * the caller can retry retirement after a transient
                         * shared-lock failure. */
                        record->operation_active = 0u;
                        result = release_error;
                    } else {
                        --gate->transaction_references;
                        retired_internal = operation->internal;
                        rinfs_memset(record->handle, 0,
                                     sizeof(*record->handle));
                        rinfs_memset(record, 0, sizeof(*record));
                        if (gate->transaction_references == 0u &&
                            gate->teardown_active == 0u)
                            rinfs_memset(gate, 0, sizeof(*gate));
                        result = RINFS_OK;
                    }
                }
            } else {
                record->operation_active = 0u;
                result = RINFS_OK;
            }
        }
    }
    rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
    /* Retain the transaction object unless registry retirement succeeds, so
     * a failed cleanup cannot leave a public handle pointing at freed memory. */
    if (result == RINFS_OK && retired_internal)
        rinfs_restore_internal_destroy(retired_internal);
    rinfs_restore_internal_scope_leave(&operation->internal_scope);
    rinfs_memset(operation, 0, sizeof(*operation));
    return result;
}

static int rinfs_restore_mount_teardown_begin(RinFS_Mount* mount,
                                              uint64_t mount_epoch) {
    RinFS_RestoreMountGateRecord* gate;
    uint32_t free_gate = RINFS_MAX_RESTORE_MOUNT_GATES;
    if (!mount) return RINFS_ERR_INVAL;
    rinfs_spin_lock(&g_rinfs_restore_transaction_lock);
    if (!rinfs_restore_transaction_registry_audit_locked()) {
        rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
        return RINFS_ERR_CORRUPT;
    }
    gate = rinfs_restore_mount_gate_find_locked(mount);
    if (gate) {
        if (gate->transaction_references != 0u ||
            gate->teardown_active != 0u) {
            rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
            return RINFS_ERR_PENDING;
        }
        gate->mount_epoch = mount_epoch;
        gate->teardown_active = 1u;
    } else {
        for (uint32_t index = 0u;
             index < RINFS_MAX_RESTORE_MOUNT_GATES; ++index) {
            if (!g_rinfs_restore_mount_gates[index].mount) {
                free_gate = index;
                break;
            }
        }
        if (free_gate == RINFS_MAX_RESTORE_MOUNT_GATES) {
            rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
            return RINFS_ERR_NOSPC;
        }
        gate = &g_rinfs_restore_mount_gates[free_gate];
        gate->mount = mount;
        /* The kernel VFS retires the public mount epoch before entering the
         * library unmount path. Keep a private teardown sentinel so a new
         * transaction cannot enter while that retired mount is dismantled. */
        gate->mount_epoch = mount_epoch != 0u ? mount_epoch : UINT64_MAX;
        gate->teardown_active = 1u;
    }
    rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
    return RINFS_OK;
}

static void rinfs_restore_mount_teardown_end(RinFS_Mount* mount,
                                             uint64_t mount_epoch,
                                             int unmounted) {
    RinFS_RestoreMountGateRecord* gate;
    (void)mount_epoch;
    (void)unmounted;
    if (!mount) return;
    rinfs_spin_lock(&g_rinfs_restore_transaction_lock);
    if (rinfs_restore_transaction_registry_audit_locked()) {
        gate = rinfs_restore_mount_gate_find_locked(mount);
        if (gate && gate->teardown_active != 0u &&
            gate->transaction_references == 0u)
            rinfs_memset(gate, 0, sizeof(*gate));
    }
    rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
}

/* Recovery can rewrite the root while replaying a pending restore record.
 * Once a shared mount has been published, give that work the same owner-ledger
 * exclusion as a live restore transaction. A teardown-shaped local record
 * prevents another thread in this process from entering while disk I/O runs. */
static int rinfs_restore_mount_recovery_begin(
    RinFS_Mount* mount, uint64_t mount_epoch) {
    RinFS_RestoreMountGateRecord* gate;
    uint32_t free_gate = RINFS_MAX_RESTORE_MOUNT_GATES;
    uint32_t owner_row = 0u;
    uint64_t owner_cookie = 0u;
    int error;
    if (!mount || mount_epoch == 0u) return RINFS_ERR_INVAL;
    rinfs_spin_lock(&g_rinfs_restore_transaction_lock);
    if (!rinfs_restore_transaction_registry_audit_locked()) {
        rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
        return RINFS_ERR_CORRUPT;
    }
    if (rinfs_restore_mount_gate_find_locked(mount)) {
        rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
        return RINFS_ERR_PENDING;
    }
    for (uint32_t index = 0u;
         index < RINFS_MAX_RESTORE_MOUNT_GATES; ++index) {
        if (!g_rinfs_restore_mount_gates[index].mount) {
            free_gate = index;
            break;
        }
    }
    if (free_gate == RINFS_MAX_RESTORE_MOUNT_GATES) {
        rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
        return RINFS_ERR_NOSPC;
    }
    error = rinfs_restore_shared_gate_claim(
        mount, mount_epoch, &owner_row, &owner_cookie, 1, 1);
    if (error != RINFS_OK) {
        rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
        return error;
    }
    gate = &g_rinfs_restore_mount_gates[free_gate];
    rinfs_memset(gate, 0, sizeof(*gate));
    gate->mount = mount;
    gate->mount_epoch = mount_epoch;
    gate->teardown_active = 1u;
    gate->shared_owner_row = owner_row;
    gate->shared_owner_cookie = owner_cookie;
    if (!rinfs_restore_transaction_registry_audit_locked()) {
        int release_error = rinfs_restore_shared_gate_release(
            mount, mount_epoch, owner_row, owner_cookie);
        if (release_error == RINFS_OK)
            rinfs_memset(gate, 0, sizeof(*gate));
        rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
        return release_error != RINFS_OK ? release_error
                                         : RINFS_ERR_CORRUPT;
    }
    rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
    return RINFS_OK;
}

static int rinfs_restore_mount_recovery_end(
    RinFS_Mount* mount, uint64_t mount_epoch) {
    RinFS_RestoreMountGateRecord* gate;
    int error;
    if (!mount || mount_epoch == 0u) return RINFS_ERR_INVAL;
    rinfs_spin_lock(&g_rinfs_restore_transaction_lock);
    if (!rinfs_restore_transaction_registry_audit_locked()) {
        rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
        return RINFS_ERR_CORRUPT;
    }
    gate = rinfs_restore_mount_gate_find_locked(mount);
    if (!gate || gate->mount_epoch != mount_epoch ||
        gate->transaction_references != 0u ||
        gate->teardown_active == 0u) {
        rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
        return RINFS_ERR_CORRUPT;
    }
    error = rinfs_restore_shared_gate_release(
        mount, mount_epoch, gate->shared_owner_row,
        gate->shared_owner_cookie);
    if (error == RINFS_OK) rinfs_memset(gate, 0, sizeof(*gate));
    rinfs_spin_unlock(&g_rinfs_restore_transaction_lock);
    return error;
}

typedef struct {
    uint64_t inode_number;
    uint64_t parent_inode;
    uint32_t inode_generation;
    char name[RINFS_NAME_MAX + 1u];
} RinFS_RestoreDeleteFrame;

_Static_assert(sizeof(RinFS_RestoreRecord) <=
                   sizeof(((RinFS_Superblock*)0)->s_padding),
               "RinFS restore record exceeds superblock padding");

static uint32_t rinfs_restore_checksum(const void* bytes, uint32_t size,
                                       uint32_t checksum_offset) {
    uint8_t local[sizeof(RinFS_RestoreRecord) >
                  sizeof(RinFS_RestoreMetadataRecord)
                      ? sizeof(RinFS_RestoreRecord)
                      : sizeof(RinFS_RestoreMetadataRecord)];
    uint32_t index;
    if (!bytes || size > sizeof(local) ||
        checksum_offset > size || size - checksum_offset < sizeof(uint32_t))
        return 0u;
    rinfs_memcpy(local, bytes, size);
    for (index = 0u; index < sizeof(uint32_t); ++index)
        local[checksum_offset + index] = 0u;
    return rinfs_checksum(local, size);
}

static int rinfs_restore_times_valid(const RinFS_InodeTimes* times) {
    return times &&
           (times->valid_mask & ~RINFS_INODE_TIME_MASK) == 0u &&
           times->reserved == 0u &&
           times->birth.nanoseconds < 1000000000u &&
           times->birth.reserved == 0u &&
           times->access.nanoseconds < 1000000000u &&
           times->access.reserved == 0u &&
           times->write.nanoseconds < 1000000000u &&
           times->write.reserved == 0u;
}

static int rinfs_restore_mode_valid(uint16_t mode) {
    uint16_t type = (uint16_t)((mode >> 12u) & 0x0fu);
    return type == RINFS_FT_DIR || type == RINFS_FT_REG ||
           type == RINFS_FT_LNK;
}

static int rinfs_restore_record_valid(const RinFS_RestoreRecord* record,
                                     const RinFS_Mount* mount) {
    uint32_t expected;
    if (!record || !mount || record->magic != RINFS_RESTORE_RECORD_MAGIC ||
        record->version != RINFS_RESTORE_VERSION ||
        record->phase < RINFS_RESTORE_PHASE_RECEIVING ||
        record->phase > RINFS_RESTORE_PHASE_ABORTING ||
        record->root_metadata_valid > 1u ||
        (record->root_metadata_valid != 0u &&
         (!rinfs_restore_mode_valid(record->root_mode) ||
          ((record->root_mode >> 12u) & 0x0fu) != RINFS_FT_DIR ||
          (record->root_flags & (uint16_t)~RINFS_RESTORE_PERSISTENT_FLAGS) != 0u ||
          !rinfs_restore_times_valid(&record->root_times) ||
          record->root_change_time_seconds < 0)) ||
        (mount->sb.s_incompat_features &
         RINFS_FEATURE_INCOMPAT_RESTORE_PENDING) == 0u)
        return 0;
    expected = rinfs_restore_checksum(record, sizeof(*record),
        (uint32_t)__builtin_offsetof(RinFS_RestoreRecord, checksum));
    return record->checksum == expected;
}

static int rinfs_restore_record_load(RinFS_Mount* mount,
                                     RinFS_RestoreRecord* record,
                                     int* present_out) {
    uint32_t magic;
    if (!mount || !record || !present_out) return RINFS_ERR_INVAL;
    rinfs_memcpy(&magic, mount->sb.s_padding, sizeof(magic));
    *present_out = 0;
    if (magic != RINFS_RESTORE_RECORD_MAGIC) {
        if ((mount->sb.s_incompat_features &
             RINFS_FEATURE_INCOMPAT_RESTORE_PENDING) != 0u)
            return RINFS_ERR_CORRUPT;
        return RINFS_OK;
    }
    if (sizeof(*record) > sizeof(mount->sb.s_padding))
        return RINFS_ERR_CORRUPT;
    rinfs_memcpy(record, mount->sb.s_padding, sizeof(*record));
    if (!rinfs_restore_record_valid(record, mount))
        return RINFS_ERR_CORRUPT;
    *present_out = 1;
    return RINFS_OK;
}

static int rinfs_restore_record_store(RinFS_Mount* mount,
                                      RinFS_RestoreRecord* record) {
    int error;
    if (!mount || !mount->mounted || mount->readonly || !record)
        return RINFS_ERR_ROFS;
    record->magic = RINFS_RESTORE_RECORD_MAGIC;
    record->version = RINFS_RESTORE_VERSION;
    record->checksum = 0u;
    record->checksum = rinfs_restore_checksum(record, sizeof(*record),
        (uint32_t)__builtin_offsetof(RinFS_RestoreRecord, checksum));
    rinfs_memcpy(mount->sb.s_padding, record, sizeof(*record));
    mount->sb.s_incompat_features |=
        RINFS_FEATURE_INCOMPAT_RESTORE_PENDING;
    error = rinfs_sync(mount);
    if (error != RINFS_OK) rinfs_mount_force_readonly(mount);
    return error;
}

static int rinfs_restore_record_clear(RinFS_Mount* mount) {
    int error;
    if (!mount || !mount->mounted) return RINFS_ERR_INVAL;
    if (mount->readonly) return RINFS_ERR_ROFS;
    rinfs_memset(mount->sb.s_padding, 0, sizeof(RinFS_RestoreRecord));
    mount->sb.s_incompat_features &=
        ~RINFS_FEATURE_INCOMPAT_RESTORE_PENDING;
    error = rinfs_sync(mount);
    if (error != RINFS_OK) rinfs_mount_force_readonly(mount);
    return error;
}

static int rinfs_restore_lookup_child(RinFS_Mount* mount, uint64_t parent,
                                      const char* name, uint8_t type,
                                      uint64_t* inode_out) {
    RinFS_Inode inode;
    uint64_t child = 0u;
    int error;
    if (!mount || !name || !inode_out) return RINFS_ERR_INVAL;
    error = rinfs_lookup(mount, parent, name, &child);
    if (error != RINFS_OK) return error;
    if (child == 0u || child > mount->sb.s_inode_count)
        return RINFS_ERR_CORRUPT;
    error = rinfs_inode_read(mount, child, &inode);
    if (error != RINFS_OK) return error;
    if (((inode.i_mode >> 12u) & 0x0fu) != type)
        return RINFS_ERR_CORRUPT;
    *inode_out = child;
    return RINFS_OK;
}

static int rinfs_restore_validate_child(RinFS_Mount* mount, uint64_t parent,
                                        const char* name, uint8_t type,
                                        uint64_t* inode_field,
                                        int required) {
    uint64_t observed = 0u;
    int error = rinfs_restore_lookup_child(mount, parent, name, type,
                                           &observed);
    if (error == RINFS_ERR_NOENT)
        return required ? RINFS_ERR_CORRUPT : RINFS_OK;
    if (error != RINFS_OK) return error;
    if (*inode_field != 0u && *inode_field != observed)
        return RINFS_ERR_CORRUPT;
    *inode_field = observed;
    return RINFS_OK;
}

static int rinfs_restore_record_refresh_children(
    RinFS_Mount* mount, RinFS_RestoreRecord* record) {
    uint64_t tx = 0u;
    int error;
    int required = record->phase == RINFS_RESTORE_PHASE_MOVING_OLD ||
                   record->phase == RINFS_RESTORE_PHASE_INSTALLING;
    error = rinfs_restore_lookup_child(mount, RINFS_INODE_ROOT,
        RINFS_RESTORE_TRANSACTION_NAME, RINFS_FT_DIR, &tx);
    if (error != RINFS_OK) return error;
    if (record->transaction_inode != 0u && record->transaction_inode != tx)
        return RINFS_ERR_CORRUPT;
    record->transaction_inode = tx;
    error = rinfs_restore_validate_child(mount, tx,
        RINFS_RESTORE_STAGE_NAME, RINFS_FT_DIR,
        &record->staging_inode, required);
    if (error != RINFS_OK) return error;
    error = rinfs_restore_validate_child(mount, tx,
        RINFS_RESTORE_OLD_NAME, RINFS_FT_DIR,
        &record->old_inode, required);
    if (error != RINFS_OK) return error;
    error = rinfs_restore_validate_child(mount, tx,
        RINFS_RESTORE_MAP_NAME, RINFS_FT_REG,
        &record->map_inode, required);
    if (error != RINFS_OK) return error;
    return rinfs_restore_validate_child(mount, tx,
        RINFS_RESTORE_METADATA_NAME, RINFS_FT_REG,
        &record->metadata_inode, required);
}

static int rinfs_restore_remove_tree_contents(RinFS_Mount* mount,
                                             uint64_t root_inode) {
    RinFS_RestoreDeleteFrame* stack = NULL;
    uint8_t* visited = NULL;
    uint64_t visited_size64;
    uint32_t capacity = (uint32_t)(RINFS_PATH_MAX / 2u + 1u);
    uint32_t depth = 0u;
    int result = RINFS_OK;
    if (!mount || root_inode < RINFS_INODE_FIRST ||
        root_inode > mount->sb.s_inode_count)
        return RINFS_ERR_INVAL;
    if (mount->sb.s_inode_count > UINT64_MAX - 7u)
        return RINFS_ERR_NOSPC;
    visited_size64 = (mount->sb.s_inode_count + 7u) / 8u;
    if (visited_size64 == 0u || visited_size64 > (uint64_t)SIZE_MAX ||
        (uint64_t)capacity * sizeof(*stack) > (uint64_t)SIZE_MAX)
        return RINFS_ERR_NOSPC;
    stack = (RinFS_RestoreDeleteFrame*)rinfs_malloc(
        (size_t)capacity * sizeof(*stack));
    visited = (uint8_t*)rinfs_malloc((size_t)visited_size64);
    if (!stack || !visited) {
        result = RINFS_ERR_NOMEM;
        goto done;
    }
    rinfs_memset(stack, 0, (size_t)capacity * sizeof(*stack));
    rinfs_memset(visited, 0, (size_t)visited_size64);
    stack[0].inode_number = root_inode;
    {
        uint64_t bit = root_inode - 1u;
        visited[bit / 8u] |= (uint8_t)(1u << (bit % 8u));
    }

    for (;;) {
        RinFS_RestoreDeleteFrame* frame = &stack[depth];
        RinFS_Dir directory;
        RinFS_DirEntry entry;
        int found = 0;
        int error = rinfs_opendir_ino(mount, frame->inode_number,
                                      &directory);
        if (error != RINFS_OK) {
            result = error;
            break;
        }
        for (;;) {
            error = rinfs_readdir(&directory, &entry);
            if (error < 0) {
                result = error;
                break;
            }
            if (error == 0) break;
            if ((entry.d_name_len == 1u && entry.d_name[0] == '.') ||
                (entry.d_name_len == 2u && entry.d_name[0] == '.' &&
                 entry.d_name[1] == '.'))
                continue;
            if (entry.d_name_len == 0u ||
                entry.d_name[entry.d_name_len] != '\0' ||
                entry.d_inode == 0u ||
                entry.d_inode > mount->sb.s_inode_count) {
                result = RINFS_ERR_CORRUPT;
                break;
            }
            found = 1;
            break;
        }
        if (rinfs_closedir(&directory) != RINFS_OK && result == RINFS_OK)
            result = RINFS_ERR_IO;
        if (result != RINFS_OK) break;
        if (found) {
            RinFS_Inode child_inode;
            uint32_t child_type = (entry.d_file_type & 0x0fu);
            error = rinfs_inode_read(mount, entry.d_inode, &child_inode);
            if (error != RINFS_OK) {
                result = error;
                break;
            }
            if (((child_inode.i_mode >> 12u) & 0x0fu) != child_type) {
                result = RINFS_ERR_CORRUPT;
                break;
            }
            if (child_type == RINFS_FT_DIR) {
                uint64_t bit = entry.d_inode - 1u;
                uint8_t mask = (uint8_t)(1u << (bit % 8u));
                if ((visited[bit / 8u] & mask) != 0u ||
                    depth + 1u >= capacity) {
                    result = RINFS_ERR_CORRUPT;
                    break;
                }
                visited[bit / 8u] |= mask;
                ++depth;
                stack[depth].inode_number = entry.d_inode;
                stack[depth].parent_inode = frame->inode_number;
                stack[depth].inode_generation = child_inode.i_generation;
                rinfs_memcpy(stack[depth].name, entry.d_name,
                             (uint32_t)entry.d_name_len + 1u);
                continue;
            }
            error = rinfs_unlink_expected(mount, frame->inode_number,
                entry.d_name, entry.d_inode, child_inode.i_generation);
            if (error != RINFS_OK) {
                result = error;
                break;
            }
            continue;
        }
        if (depth == 0u) break;
        frame = &stack[depth];
        error = rinfs_rmdir_expected(mount, frame->parent_inode,
                                     frame->name, frame->inode_number,
                                     frame->inode_generation);
        if (error != RINFS_OK) {
            result = error;
            break;
        }
        --depth;
    }

done:
    if (visited) rinfs_free(visited);
    if (stack) rinfs_free(stack);
    return result;
}

static int rinfs_restore_file_sync_close(RinFS_File* file) {
    RinFS_Mount* mount;
    int error;
    int close_error;
    if (!file || !file->in_use) return RINFS_ERR_INVAL;
    mount = file->mount;
    error = rinfs_fsync(file);
    close_error = rinfs_close(file);
    if (error == RINFS_OK) error = close_error;
    if (error == RINFS_OK) error = rinfs_sync(mount);
    return error;
}

static int rinfs_restore_metadata_record_valid(
    const RinFS_RestoreMetadataRecord* metadata) {
    uint32_t expected;
    if (!metadata || metadata->magic != RINFS_RESTORE_TX_MAGIC ||
        metadata->reserved != 0u || metadata->inode_number == 0u ||
        metadata->inode_generation == 0u ||
        !rinfs_restore_mode_valid(metadata->mode) ||
        (metadata->persistent_flags &
         (uint16_t)~RINFS_RESTORE_PERSISTENT_FLAGS) != 0u ||
        !rinfs_restore_times_valid(&metadata->times) ||
        metadata->change_time_seconds < 0)
        return 0;
    expected = rinfs_restore_checksum(metadata, sizeof(*metadata),
        (uint32_t)__builtin_offsetof(RinFS_RestoreMetadataRecord, checksum));
    return metadata->checksum == expected;
}

static int rinfs_restore_apply_metadata(
    RinFS_Mount* mount, uint64_t inode_number, uint32_t generation,
    uint16_t mode, uint16_t persistent_flags, uint32_t uid, uint32_t gid,
    const RinFS_InodeTimes* times, int64_t change_time_seconds) {
    RinFS_Inode inode;
    uint32_t inode_type = (uint32_t)((mode >> 12u) & 0x0fu);
    int error;
    if (!mount || inode_number == 0u ||
        inode_number > mount->sb.s_inode_count || generation == 0u ||
        !rinfs_restore_mode_valid(mode) ||
        (persistent_flags &
         (uint16_t)~RINFS_RESTORE_PERSISTENT_FLAGS) != 0u ||
        !rinfs_restore_times_valid(times) || change_time_seconds < 0)
        return RINFS_ERR_CORRUPT;
    error = rinfs_inode_read(mount, inode_number, &inode);
    if (error != RINFS_OK) return error;
    if (inode.i_generation != generation ||
        ((inode.i_mode >> 12u) & 0x0fu) != inode_type)
        return RINFS_ERR_STALE;

    if (times->valid_mask != 0u) {
        int has_nanoseconds = times->birth.nanoseconds != 0u ||
                              times->access.nanoseconds != 0u ||
                              times->write.nanoseconds != 0u;
        if ((mount->sb.s_incompat_features &
             RINFS_FEATURE_INCOMPAT_NANO_TIMESTAMPS) != 0u) {
            error = rinfs_inode_set_times_precise(
                mount, inode_number, times->valid_mask, &times->birth,
                &times->access, &times->write, &inode);
        } else if (has_nanoseconds) {
            return RINFS_ERR_NOT_SUPPORTED;
        } else {
            if (((times->valid_mask & RINFS_INODE_TIME_BIRTH) != 0u &&
                 times->birth.seconds < 0) ||
                ((times->valid_mask & RINFS_INODE_TIME_ACCESS) != 0u &&
                 times->access.seconds < 0) ||
                ((times->valid_mask & RINFS_INODE_TIME_WRITE) != 0u &&
                 times->write.seconds < 0))
                return RINFS_ERR_NOT_SUPPORTED;
            error = rinfs_inode_set_times(
                mount, inode_number, times->valid_mask,
                (uint64_t)times->birth.seconds,
                (uint64_t)times->access.seconds,
                (uint64_t)times->write.seconds, &inode);
        }
        if (error != RINFS_OK) return error;
    }

    error = rinfs_inode_read(mount, inode_number, &inode);
    if (error != RINFS_OK) return error;
    if (inode.i_generation != generation ||
        ((inode.i_mode >> 12u) & 0x0fu) != inode_type)
        return RINFS_ERR_STALE;
    inode.i_mode = mode;
    inode.i_flags = (uint16_t)((inode.i_flags &
        (uint16_t)~RINFS_RESTORE_PERSISTENT_FLAGS) | persistent_flags);
    inode.i_uid = uid;
    inode.i_gid = gid;
    inode.i_ctime = (uint64_t)change_time_seconds;
    error = rinfs_inode_write(mount, inode_number, &inode);
    if (error != RINFS_OK) return error;
    return rinfs_sync(mount);
}

static int rinfs_restore_apply_metadata_log(RinFS_Mount* mount,
                                            RinFS_RestoreRecord* record) {
    RinFS_File file;
    uint64_t index;
    int error = rinfs_open_ino(mount, record->metadata_inode,
        RIN_VFS_OPEN_READ, &file);
    if (error != RINFS_OK) return error;
    for (index = 0u; index < record->metadata_entries; ++index) {
        RinFS_RestoreMetadataRecord metadata;
        uint64_t offset;
        int64_t read_size;
        if (index > UINT64_MAX / sizeof(metadata)) {
            error = RINFS_ERR_CORRUPT;
            break;
        }
        offset = index * sizeof(metadata);
        read_size = rinfs_pread(&file, &metadata, sizeof(metadata), offset);
        if (read_size != (int64_t)sizeof(metadata) ||
            !rinfs_restore_metadata_record_valid(&metadata) ||
            metadata.inode_number > mount->sb.s_inode_count) {
            error = read_size < 0 ? (int)read_size : RINFS_ERR_CORRUPT;
            break;
        }
        error = rinfs_restore_apply_metadata(
            mount, metadata.inode_number, metadata.inode_generation,
            metadata.mode, metadata.persistent_flags, metadata.uid,
            metadata.gid, &metadata.times,
            metadata.change_time_seconds);
        if (error != RINFS_OK) break;
    }
    {
        int close_error = rinfs_close(&file);
        if (error == RINFS_OK) error = close_error;
    }
    if (error == RINFS_OK) error = rinfs_sync(mount);
    return error;
}

static int rinfs_restore_move_children(RinFS_Mount* mount,
                                       uint64_t source_inode,
                                       uint64_t destination_inode,
                                       uint64_t skip_inode) {
    for (;;) {
        RinFS_Dir directory;
        RinFS_DirEntry entry;
        char name[RINFS_NAME_MAX + 1u];
        int found = 0;
        int error = rinfs_opendir_ino(mount, source_inode, &directory);
        if (error != RINFS_OK) return error;
        for (;;) {
            error = rinfs_readdir(&directory, &entry);
            if (error < 0) break;
            if (error == 0) break;
            if ((entry.d_name_len == 1u && entry.d_name[0] == '.') ||
                (entry.d_name_len == 2u && entry.d_name[0] == '.' &&
                 entry.d_name[1] == '.') || entry.d_inode == skip_inode)
                continue;
            if (entry.d_name_len == 0u ||
                entry.d_name[entry.d_name_len] != '\0' ||
                entry.d_inode == 0u ||
                entry.d_inode > mount->sb.s_inode_count) {
                error = RINFS_ERR_CORRUPT;
                break;
            }
            rinfs_memcpy(name, entry.d_name,
                         (uint32_t)entry.d_name_len + 1u);
            found = 1;
            break;
        }
        {
            int close_error = rinfs_closedir(&directory);
            if (error >= 0 && close_error != RINFS_OK) error = close_error;
        }
        if (error < 0) return error;
        if (!found) return rinfs_sync(mount);
        error = rinfs_rename_no_replace(mount, source_inode, name,
                                        destination_inode, name);
        if (error != RINFS_OK) return error;
    }
}

static int rinfs_restore_delete_named(RinFS_Mount* mount, uint64_t parent,
                                      const char* name, uint64_t expected,
                                      uint32_t expected_type) {
    uint64_t inode_number = 0u;
    RinFS_Inode inode;
    int error = rinfs_lookup(mount, parent, name, &inode_number);
    if (error == RINFS_ERR_NOENT) return RINFS_OK;
    if (error != RINFS_OK) return error;
    if (expected != 0u && inode_number != expected)
        return RINFS_ERR_CORRUPT;
    error = rinfs_inode_read(mount, inode_number, &inode);
    if (error != RINFS_OK) return error;
    if (((inode.i_mode >> 12u) & 0x0fu) != expected_type)
        return RINFS_ERR_CORRUPT;
    if (expected_type == RINFS_FT_DIR) {
        error = rinfs_restore_remove_tree_contents(mount, inode_number);
        if (error != RINFS_OK) return error;
        return rinfs_rmdir_expected(mount, parent, name, inode_number,
                                    inode.i_generation);
    }
    return rinfs_unlink_expected(mount, parent, name, inode_number,
                                 inode.i_generation);
}

static int rinfs_restore_directory_empty(RinFS_Mount* mount,
                                         uint64_t inode_number) {
    RinFS_Dir directory;
    RinFS_DirEntry entry;
    int error = rinfs_opendir_ino(mount, inode_number, &directory);
    if (error != RINFS_OK) return error;
    for (;;) {
        error = rinfs_readdir(&directory, &entry);
        if (error <= 0) break;
        if ((entry.d_name_len == 1u && entry.d_name[0] == '.') ||
            (entry.d_name_len == 2u && entry.d_name[0] == '.' &&
             entry.d_name[1] == '.'))
            continue;
        error = RINFS_ERR_NOTEMPTY;
        break;
    }
    {
        int close_error = rinfs_closedir(&directory);
        if (error >= 0 && close_error != RINFS_OK) error = close_error;
    }
    return error == 0 ? RINFS_OK : error;
}

static int rinfs_restore_transaction_cleanup_children(
    RinFS_Mount* mount, RinFS_RestoreRecord* record) {
    uint64_t tx = record->transaction_inode;
    int error;
    if (tx == 0u) {
        error = rinfs_lookup(mount, RINFS_INODE_ROOT,
                             RINFS_RESTORE_TRANSACTION_NAME, &tx);
        if (error == RINFS_ERR_NOENT) return RINFS_OK;
        if (error != RINFS_OK) return error;
        record->transaction_inode = tx;
    }
    error = rinfs_restore_delete_named(mount, tx,
        RINFS_RESTORE_STAGE_NAME, record->staging_inode, RINFS_FT_DIR);
    if (error != RINFS_OK) return error;
    error = rinfs_restore_delete_named(mount, tx,
        RINFS_RESTORE_OLD_NAME, record->old_inode, RINFS_FT_DIR);
    if (error != RINFS_OK) return error;
    error = rinfs_restore_delete_named(mount, tx,
        RINFS_RESTORE_MAP_NAME, record->map_inode, RINFS_FT_REG);
    if (error != RINFS_OK) return error;
    error = rinfs_restore_delete_named(mount, tx,
        RINFS_RESTORE_METADATA_NAME, record->metadata_inode,
        RINFS_FT_REG);
    if (error != RINFS_OK) return error;
    return rinfs_restore_directory_empty(mount, tx);
}

static int rinfs_restore_transaction_remove_dir(RinFS_Mount* mount,
                                                RinFS_RestoreRecord* record) {
    uint64_t tx = 0u;
    RinFS_Inode inode;
    int error = rinfs_lookup(mount, RINFS_INODE_ROOT,
                             RINFS_RESTORE_TRANSACTION_NAME, &tx);
    if (error == RINFS_ERR_NOENT) {
        if (record->phase == RINFS_RESTORE_PHASE_DONE ||
            record->phase == RINFS_RESTORE_PHASE_ABORTING) {
            record->transaction_inode = 0u;
            return RINFS_OK;
        }
        return RINFS_ERR_CORRUPT;
    }
    if (error != RINFS_OK) return error;
    if (record->transaction_inode != 0u &&
        record->transaction_inode != tx)
        return RINFS_ERR_CORRUPT;
    error = rinfs_restore_directory_empty(mount, tx);
    if (error != RINFS_OK) return error;
    error = rinfs_inode_read(mount, tx, &inode);
    if (error != RINFS_OK) return error;
    error = rinfs_rmdir_expected(mount, RINFS_INODE_ROOT,
                                 RINFS_RESTORE_TRANSACTION_NAME, tx,
                                 inode.i_generation);
    if (error != RINFS_OK) return error;
    record->transaction_inode = 0u;
    record->staging_inode = 0u;
    record->old_inode = 0u;
    record->map_inode = 0u;
    record->metadata_inode = 0u;
    return rinfs_sync(mount);
}

static void rinfs_restore_internal_destroy(
    RinFS_RestoreTransactionInternal* internal) {
    if (internal) {
        rinfs_memset(internal, 0, sizeof(*internal));
        rinfs_free(internal);
    }
}

static int rinfs_restore_transaction_validate_internal(
    RinFS_RestoreTransactionInternal* internal) {
    if (!internal || internal->magic != RINFS_RESTORE_TX_MAGIC ||
        !internal->mount)
        return RINFS_ERR_CORRUPT;
    if (internal->mount_epoch == 0u ||
        internal->mount->mount_epoch != internal->mount_epoch ||
        !internal->mount->mounted)
        return RINFS_ERR_STALE;
    if (internal->mount->readonly) return RINFS_ERR_ROFS;
    if (internal->record.phase != RINFS_RESTORE_PHASE_RECEIVING ||
        (internal->mount->sb.s_incompat_features &
         RINFS_FEATURE_INCOMPAT_RESTORE_PENDING) == 0u)
        return RINFS_ERR_PENDING;
    return RINFS_OK;
}

static int rinfs_restore_recover_cleanup_leaks(RinFS_Mount* mount) {
    RinFS_FullCheckReport report;
    int error = rinfs_check_full(mount, &report);
    if (error == RINFS_ERR_CORRUPT &&
        report.issues == RINFS_FULL_ISSUE_LEAKED_BLOCK &&
        report.leaked_blocks != 0u) {
        uint32_t mount_flags = mount->mount_flags;
        mount->mount_flags |= RINFS_MNT_REPAIR;
        error = rinfs_repair_full(
            mount, RINFS_FULL_REPAIR_SAFE_METADATA, &report);
        mount->mount_flags = mount_flags;
        return error;
    }
    if (error != RINFS_OK || report.issues != 0u)
        return error != RINFS_OK ? error : RINFS_ERR_CORRUPT;
    return RINFS_OK;
}

static int rinfs_restore_commit_record(RinFS_Mount* mount,
                                       RinFS_RestoreRecord* record,
                                       int recover_cleanup_leaks) {
    int error;
    if (record->phase == RINFS_RESTORE_PHASE_MOVING_OLD) {
        error = rinfs_restore_record_refresh_children(mount, record);
        if (error != RINFS_OK) return error;
        error = rinfs_restore_move_children(mount, RINFS_INODE_ROOT,
            record->old_inode, record->transaction_inode);
        if (error != RINFS_OK) return error;
        record->phase = RINFS_RESTORE_PHASE_INSTALLING;
        error = rinfs_restore_record_store(mount, record);
        if (error != RINFS_OK) return error;
    }
    if (record->phase == RINFS_RESTORE_PHASE_INSTALLING) {
        error = rinfs_restore_record_refresh_children(mount, record);
        if (error != RINFS_OK) return error;
        error = rinfs_restore_move_children(mount, record->staging_inode,
                                             RINFS_INODE_ROOT, 0u);
        if (error != RINFS_OK) return error;
        error = rinfs_xattr_copy(mount, record->staging_inode,
                                 mount, RINFS_INODE_ROOT);
        if (error != RINFS_OK) return error;
        error = rinfs_restore_apply_metadata_log(mount, record);
        if (error != RINFS_OK) return error;
        error = rinfs_sync(mount);
        if (error != RINFS_OK) return error;
        record->phase = RINFS_RESTORE_PHASE_CLEANING;
        error = rinfs_restore_record_store(mount, record);
        if (error != RINFS_OK) return error;
    }
    if (record->phase == RINFS_RESTORE_PHASE_CLEANING) {
        error = rinfs_restore_record_refresh_children(mount, record);
        if (error != RINFS_OK) return error;
        error = rinfs_restore_transaction_cleanup_children(mount, record);
        if (error != RINFS_OK) return error;
        record->phase = RINFS_RESTORE_PHASE_DONE;
        error = rinfs_restore_record_store(mount, record);
        if (error != RINFS_OK) return error;
    }
    if (record->phase == RINFS_RESTORE_PHASE_DONE) {
        error = rinfs_restore_transaction_remove_dir(mount, record);
        if (error != RINFS_OK) return error;
        if (recover_cleanup_leaks) {
            error = rinfs_restore_recover_cleanup_leaks(mount);
            if (error != RINFS_OK) return error;
        }
        if (record->root_metadata_valid == 0u)
            return RINFS_ERR_CORRUPT;
        {
            RinFS_Inode root;
            error = rinfs_inode_read(mount, RINFS_INODE_ROOT, &root);
            if (error != RINFS_OK) return error;
            error = rinfs_restore_apply_metadata(
                mount, RINFS_INODE_ROOT, root.i_generation,
                record->root_mode, record->root_flags, record->root_uid,
                record->root_gid, &record->root_times,
                record->root_change_time_seconds);
        }
        if (error != RINFS_OK) return error;
        return rinfs_restore_record_clear(mount);
    }
    return RINFS_ERR_CORRUPT;
}

static int rinfs_restore_abort_record(RinFS_Mount* mount,
                                      RinFS_RestoreRecord* record) {
    int error;
    if (record->phase == RINFS_RESTORE_PHASE_RECEIVING) {
        record->phase = RINFS_RESTORE_PHASE_ABORTING;
        error = rinfs_restore_record_store(mount, record);
        if (error != RINFS_OK) return error;
    }
    if (record->phase != RINFS_RESTORE_PHASE_ABORTING)
        return RINFS_ERR_PENDING;

    error = rinfs_restore_record_refresh_children(mount, record);
    if (error == RINFS_ERR_NOENT) {
        uint64_t transaction_inode = 0u;
        int lookup = rinfs_lookup(mount, RINFS_INODE_ROOT,
            RINFS_RESTORE_TRANSACTION_NAME, &transaction_inode);
        if (lookup == RINFS_ERR_NOENT)
            return rinfs_restore_record_clear(mount);
        if (lookup != RINFS_OK) return lookup;
        return RINFS_ERR_CORRUPT;
    }
    if (error != RINFS_OK) return error;
    if (record->old_inode != 0u) {
        error = rinfs_restore_directory_empty(mount, record->old_inode);
        if (error != RINFS_OK) return error == RINFS_ERR_NOTEMPTY
            ? RINFS_ERR_CORRUPT : error;
    }
    error = rinfs_restore_transaction_cleanup_children(mount, record);
    if (error != RINFS_OK) return error;
    error = rinfs_restore_transaction_remove_dir(mount, record);
    if (error != RINFS_OK) return error;
    return rinfs_restore_record_clear(mount);
}

static int rinfs_restore_transaction_commit_core(
    RinFS_RestoreTransactionInternal* internal) {
    int error;
    if (internal->record.phase == RINFS_RESTORE_PHASE_RECEIVING) {
        if (internal->record.root_metadata_valid == 0u)
            return RINFS_ERR_INVAL;
        internal->record.phase = RINFS_RESTORE_PHASE_MOVING_OLD;
        error = rinfs_restore_record_store(internal->mount,
                                            &internal->record);
        if (error != RINFS_OK) return error;
    }
    if (internal->record.phase != RINFS_RESTORE_PHASE_MOVING_OLD &&
        internal->record.phase != RINFS_RESTORE_PHASE_INSTALLING &&
        internal->record.phase != RINFS_RESTORE_PHASE_CLEANING &&
        internal->record.phase != RINFS_RESTORE_PHASE_DONE)
        return RINFS_ERR_PENDING;
    error = rinfs_restore_commit_record(internal->mount, &internal->record,
                                        0);
    if (error != RINFS_OK) {
        rinfs_mount_force_readonly(internal->mount);
        return error;
    }
    return RINFS_OK;
}

int rinfs_restore_transaction_commit(
    RinFS_RestoreTransactionV1* transaction) {
    RinFS_RestoreTransactionOperation operation;
    RinFS_RestoreTransactionInternal* internal = NULL;
    int error = rinfs_restore_transaction_operation_begin(
        transaction, 0, &operation, &internal);
    int release_error;
    if (error != RINFS_OK) return error;
    error = rinfs_restore_transaction_commit_core(internal);
    release_error = rinfs_restore_transaction_operation_end(
        &operation, error == RINFS_OK);
    return release_error == RINFS_OK ? error : release_error;
}

static int rinfs_restore_transaction_abort_core(
    RinFS_RestoreTransactionInternal* internal) {
    int error;
    if (internal->record.phase != RINFS_RESTORE_PHASE_RECEIVING &&
        internal->record.phase != RINFS_RESTORE_PHASE_ABORTING)
        return RINFS_ERR_PENDING;
    error = rinfs_restore_abort_record(internal->mount, &internal->record);
    if (error != RINFS_OK) {
        rinfs_mount_force_readonly(internal->mount);
        return error;
    }
    return RINFS_OK;
}

int rinfs_restore_transaction_abort(
    RinFS_RestoreTransactionV1* transaction) {
    RinFS_RestoreTransactionOperation operation;
    RinFS_RestoreTransactionInternal* internal = NULL;
    int error = rinfs_restore_transaction_operation_begin(
        transaction, 0, &operation, &internal);
    int release_error;
    if (error != RINFS_OK) return error;
    error = rinfs_restore_transaction_abort_core(internal);
    release_error = rinfs_restore_transaction_operation_end(
        &operation, error == RINFS_OK);
    return release_error == RINFS_OK ? error : release_error;
}

static int rinfs_restore_transaction_forget_core(
    RinFS_RestoreTransactionV1* transaction,
    RinFS_RestoreTransactionInternal* internal) {
    if (!transaction || !internal ||
        internal->magic != RINFS_RESTORE_TX_MAGIC)
        return RINFS_ERR_CORRUPT;
    /* This intentionally does not touch the volume. The checksummed pending
     * record remains authoritative and recovery runs on the next mount. */
    return RINFS_OK;
}

int rinfs_restore_transaction_forget(
    RinFS_RestoreTransactionV1* transaction) {
    RinFS_RestoreTransactionOperation operation;
    RinFS_RestoreTransactionInternal* internal = NULL;
    int error = rinfs_restore_transaction_operation_begin(
        transaction, 1, &operation, &internal);
    int release_error;
    if (error != RINFS_OK) return error;
    error = rinfs_restore_transaction_forget_core(transaction, internal);
    release_error = rinfs_restore_transaction_operation_end(
        &operation, error == RINFS_OK);
    return release_error == RINFS_OK ? error : release_error;
}

static int rinfs_restore_transaction_mount_recover_core(RinFS_Mount* mount) {
    RinFS_RestoreRecord record;
    int present = 0;
    int recovery_only;
    int restore_retry;
    int error;
    if (!mount || !mount->mounted) return RINFS_ERR_INVAL;
    recovery_only = rinfs_mount_recovery_only(mount);
    restore_retry =
        (rinfs_mount_readonly_state(mount) &
         RINFS_READONLY_RECOVERY_RESTORE_MASK) != 0u;
    /* Read the durable marker before clearing a retry fence. A failed
     * pre-replay sync or transient cache-quiescence check never changes this
     * record, so its presence identifies recovery that is safe to retry. */
    error = rinfs_restore_record_load(mount, &record, &present);
    if (error != RINFS_OK) {
        if (recovery_only && error == RINFS_ERR_CORRUPT)
            rinfs_mount_force_readonly(mount);
        return error;
    }
    if (!present) {
        if (restore_retry) {
            rinfs_mount_force_readonly(mount);
            return RINFS_ERR_CORRUPT;
        }
        if (recovery_only) return rinfs_mount_prepare_write(mount);
        return RINFS_OK;
    }
    if (recovery_only) {
        if (restore_retry)
            rinfs_mount_recovery_clear(
                mount, RINFS_READONLY_RECOVERY_RESTORE_MASK);
        error = rinfs_mount_prepare_write(mount);
        if (error != RINFS_OK) return error;
    } else if (mount->readonly) {
        return RINFS_ERR_ROFS;
    }
    /* A published mount may enter recovery with dirty pages left by work
     * completed before the restore marker became visible. Persist that state
     * while ordinary operations are excluded, then discard every clean cache
     * entry before replay can replace inode and namespace contents. */
    error = rinfs_restore_cache_sync_for_recovery(mount);
    if (error != RINFS_OK) {
        rinfs_mount_recovery_fence(
            mount, RINFS_READONLY_RECOVERY_RESTORE_SYNC, error);
        return error;
    }
    error = rinfs_restore_page_cache_quiesce(mount, 0);
    if (error == RINFS_ERR_BUSY) {
        /* Outstanding references may drain after this recovery admission is
         * released. The durable marker remains authoritative, so permit an
         * explicit retry once those references have gone away. */
        rinfs_mount_recovery_fence(
            mount, RINFS_READONLY_RECOVERY_RESTORE_CACHE, error);
        return error;
    }
    if (error != RINFS_OK) {
        rinfs_mount_force_readonly(mount);
        return error;
    }
    if (record.phase == RINFS_RESTORE_PHASE_RECEIVING ||
        record.phase == RINFS_RESTORE_PHASE_ABORTING)
        error = rinfs_restore_abort_record(mount, &record);
    else
        error = rinfs_restore_commit_record(mount, &record, 1);
    if (error != RINFS_OK) rinfs_mount_force_readonly(mount);
    return error;
}

int rinfs_restore_transaction_mount_recover(RinFS_Mount* mount) {
    uint64_t mount_epoch;
    RinFS_RestoreInternalScope internal_scope = {0u};
    int error;
    int release_error;
    if (!mount || !mount->mounted) return RINFS_ERR_INVAL;
    /* The first shared mount performs recovery before publishing its owner
     * row. Its provisional VFS range lease excludes another mount of these
     * sectors until shared_mount_ready is published. */
    if (mount->shared_mapping_base && mount->shared_mount_ready == 0u) {
        error = rinfs_restore_internal_scope_enter(&internal_scope);
        if (error != RINFS_OK) return error;
        error = rinfs_restore_transaction_mount_recover_core(mount);
        rinfs_restore_internal_scope_leave(&internal_scope);
        return error;
    }
    mount_epoch = mount->mount_epoch;
    if (mount_epoch == 0u) return RINFS_ERR_STALE;
    error = rinfs_restore_mount_recovery_begin(mount, mount_epoch);
    if (error != RINFS_OK) return error;
    error = rinfs_restore_internal_scope_enter(&internal_scope);
    if (error != RINFS_OK) {
        int release_error = rinfs_restore_mount_recovery_end(
            mount, mount_epoch);
        return release_error == RINFS_OK ? error : release_error;
    }
    error = rinfs_restore_transaction_mount_recover_core(mount);
    release_error = rinfs_restore_mount_recovery_end(mount, mount_epoch);
    rinfs_restore_internal_scope_leave(&internal_scope);
    if (release_error != RINFS_OK) {
        rinfs_mount_force_readonly(mount);
        return release_error;
    }
    return error;
}

int rinfs_restore_transaction_begin(RinFS_Mount* mount,
                                    RinFS_RestoreTransactionV1* transaction,
                                    uint32_t uid, uint32_t gid,
                                    uint64_t* staging_root_inode_out) {
    RinFS_RestoreTransactionInternal* internal;
    RinFS_RestoreInternalScope internal_scope = {0u};
    RinFS_RestoreRecord record;
    uint64_t existing = 0u;
    uint32_t handle_token = 0u;
    int present = 0;
    int error;
    if (!mount || !mount->mounted || mount->mount_epoch == 0u ||
        !transaction || !staging_root_inode_out)
        return RINFS_ERR_INVAL;
    *staging_root_inode_out = 0u;
    error = rinfs_mount_prepare_write(mount);
    if (error != RINFS_OK) return error;
    if ((mount->sb.s_incompat_features &
         RINFS_FEATURE_INCOMPAT_CONTENT_VERSION64) == 0u)
        return RINFS_ERR_INVAL;
    error = rinfs_restore_transaction_reserve(
        mount, mount->mount_epoch, transaction, &handle_token);
    if (error != RINFS_OK) return error;
    error = rinfs_restore_internal_scope_enter(&internal_scope);
    if (error != RINFS_OK) {
        int release_error = rinfs_restore_transaction_reservation_abort(
            transaction, handle_token);
        return release_error == RINFS_OK ? error : release_error;
    }
    error = rinfs_sync(mount);
    if (error != RINFS_OK) goto preflight_failed;
    error = rinfs_restore_page_cache_quiesce(mount, 0);
    if (error != RINFS_OK) {
        if (error == RINFS_ERR_CORRUPT) rinfs_mount_force_readonly(mount);
        goto preflight_failed;
    }
    error = rinfs_restore_record_load(mount, &record, &present);
    if (error != RINFS_OK) goto preflight_failed;
    if (present || (mount->sb.s_incompat_features &
                    RINFS_FEATURE_INCOMPAT_RESTORE_PENDING) != 0u) {
        error = RINFS_ERR_PENDING;
        goto preflight_failed;
    }
    error = rinfs_lookup(mount, RINFS_INODE_ROOT,
                         RINFS_RESTORE_TRANSACTION_NAME,
                         &existing);
    if (error == RINFS_OK) {
        error = RINFS_ERR_EXIST;
        goto preflight_failed;
    }
    if (error != RINFS_ERR_NOENT) goto preflight_failed;

    internal = (RinFS_RestoreTransactionInternal*)rinfs_malloc(
        sizeof(*internal));
    if (!internal) {
        error = RINFS_ERR_NOMEM;
        goto preflight_failed;
    }
    rinfs_memset(internal, 0, sizeof(*internal));
    internal->magic = RINFS_RESTORE_TX_MAGIC;
    internal->mount = mount;
    internal->mount_epoch = mount->mount_epoch;
    internal->record.phase = RINFS_RESTORE_PHASE_RECEIVING;
    error = rinfs_restore_record_store(mount, &internal->record);
    if (error != RINFS_OK) goto failed;

    error = rinfs_mkdirat_owned(mount, RINFS_INODE_ROOT,
        RINFS_RESTORE_TRANSACTION_NAME, 0700u, uid, gid,
        &internal->record.transaction_inode);
    if (error != RINFS_OK) goto failed;
    error = rinfs_restore_record_store(mount, &internal->record);
    if (error != RINFS_OK) goto failed;

    error = rinfs_mkdirat_owned(mount, internal->record.transaction_inode,
        RINFS_RESTORE_STAGE_NAME, 0700u, uid, gid,
        &internal->record.staging_inode);
    if (error != RINFS_OK) goto failed;
    error = rinfs_restore_record_store(mount, &internal->record);
    if (error != RINFS_OK) goto failed;
    error = rinfs_mkdirat_owned(mount, internal->record.transaction_inode,
        RINFS_RESTORE_OLD_NAME, 0700u, uid, gid,
        &internal->record.old_inode);
    if (error != RINFS_OK) goto failed;
    error = rinfs_restore_record_store(mount, &internal->record);
    if (error != RINFS_OK) goto failed;
    error = rinfs_createat_owned(mount, internal->record.transaction_inode,
        RINFS_RESTORE_MAP_NAME, 0600u, uid, gid,
        &internal->record.map_inode);
    if (error != RINFS_OK) goto failed;
    error = rinfs_restore_record_store(mount, &internal->record);
    if (error != RINFS_OK) goto failed;
    error = rinfs_createat_owned(mount, internal->record.transaction_inode,
        RINFS_RESTORE_METADATA_NAME, 0600u, uid, gid,
        &internal->record.metadata_inode);
    if (error != RINFS_OK) goto failed;
    error = rinfs_restore_record_store(mount, &internal->record);
    if (error != RINFS_OK) goto failed;

    error = rinfs_restore_transaction_publish(
        transaction, internal, handle_token);
    if (error != RINFS_OK) goto failed;
    *staging_root_inode_out = internal->record.staging_inode;
    rinfs_restore_internal_scope_leave(&internal_scope);
    return RINFS_OK;

preflight_failed:
    {
        int release_error = rinfs_restore_transaction_reservation_abort(
            transaction, handle_token);
        if (release_error != RINFS_OK) {
            rinfs_restore_internal_scope_leave(&internal_scope);
            return release_error;
        }
    }
    rinfs_restore_internal_scope_leave(&internal_scope);
    return error;

failed:
    if (mount->readonly == 0) {
        int cleanup_error;
        if (error == RINFS_ERR_EXIST &&
            internal->record.transaction_inode == 0u)
            cleanup_error = rinfs_restore_record_clear(mount);
        else
            cleanup_error =
                rinfs_restore_transaction_mount_recover_core(mount);
        if (cleanup_error != RINFS_OK) {
            rinfs_mount_force_readonly(mount);
            error = cleanup_error;
        }
    }
    rinfs_memset(internal, 0, sizeof(*internal));
    rinfs_free(internal);
    {
        int release_error = rinfs_restore_transaction_reservation_abort(
            transaction, handle_token);
        if (release_error != RINFS_OK) {
            rinfs_restore_internal_scope_leave(&internal_scope);
            return release_error;
        }
    }
    rinfs_restore_internal_scope_leave(&internal_scope);
    return error;
}

static int rinfs_restore_transaction_store_inode_core(
    RinFS_RestoreTransactionInternal* internal, uint64_t entry_index,
    uint64_t inode_number) {
    RinFS_File file;
    uint64_t offset;
    int64_t written;
    int error;
    error = rinfs_restore_transaction_validate_internal(internal);
    if (error != RINFS_OK) return error;
    if (inode_number == 0u ||
        inode_number > internal->mount->sb.s_inode_count ||
        entry_index != internal->record.map_entries ||
        entry_index >= internal->mount->sb.s_inode_count ||
        entry_index > UINT64_MAX / sizeof(inode_number))
        return RINFS_ERR_INVAL;
    offset = entry_index * sizeof(inode_number);
    error = rinfs_open_ino(internal->mount, internal->record.map_inode,
        RIN_VFS_OPEN_READ | RIN_VFS_OPEN_WRITE, &file);
    if (error != RINFS_OK) return error;
    written = rinfs_pwrite(&file, &inode_number, sizeof(inode_number), offset);
    if (written != (int64_t)sizeof(inode_number)) {
        error = written < 0 ? (int)written : RINFS_ERR_IO;
        {
            int close_error = rinfs_close(&file);
            return close_error == RINFS_OK ? error : close_error;
        }
    }
    error = rinfs_restore_file_sync_close(&file);
    if (error != RINFS_OK) return error;
    ++internal->record.map_entries;
    return rinfs_restore_record_store(internal->mount, &internal->record);
}

int rinfs_restore_transaction_store_inode(
    RinFS_RestoreTransactionV1* transaction, uint64_t entry_index,
    uint64_t inode_number) {
    RinFS_RestoreTransactionOperation operation;
    RinFS_RestoreTransactionInternal* internal = NULL;
    int error = rinfs_restore_transaction_operation_begin(
        transaction, 0, &operation, &internal);
    int release_error;
    if (error != RINFS_OK) return error;
    error = rinfs_restore_transaction_store_inode_core(
        internal, entry_index, inode_number);
    release_error = rinfs_restore_transaction_operation_end(&operation, 0);
    return release_error == RINFS_OK ? error : release_error;
}

static int rinfs_restore_transaction_load_inode_core(
    RinFS_RestoreTransactionInternal* internal, uint64_t entry_index,
    uint64_t* inode_number_out) {
    RinFS_File file;
    uint64_t inode_number = 0u;
    uint64_t offset;
    int64_t read_size;
    int read_error;
    int error;
    if (!inode_number_out) return RINFS_ERR_INVAL;
    *inode_number_out = 0u;
    error = rinfs_restore_transaction_validate_internal(internal);
    if (error != RINFS_OK) return error;
    if (entry_index >= internal->record.map_entries ||
        entry_index > UINT64_MAX / sizeof(inode_number))
        return RINFS_ERR_INVAL;
    offset = entry_index * sizeof(inode_number);
    error = rinfs_open_ino(internal->mount, internal->record.map_inode,
                           RIN_VFS_OPEN_READ, &file);
    if (error != RINFS_OK) return error;
    read_size = rinfs_pread(&file, &inode_number, sizeof(inode_number), offset);
    error = rinfs_close(&file);
    if (error != RINFS_OK) return error;
    read_error = read_size == (int64_t)sizeof(inode_number)
        ? RINFS_OK
        : (read_size < 0 ? (int)read_size : RINFS_ERR_CORRUPT);
    if (read_error != RINFS_OK) return read_error;
    if (inode_number == 0u ||
        inode_number > internal->mount->sb.s_inode_count)
        return RINFS_ERR_CORRUPT;
    *inode_number_out = inode_number;
    return RINFS_OK;
}

int rinfs_restore_transaction_load_inode(
    RinFS_RestoreTransactionV1* transaction, uint64_t entry_index,
    uint64_t* inode_number_out) {
    RinFS_RestoreTransactionOperation operation;
    RinFS_RestoreTransactionInternal* internal = NULL;
    int error;
    int release_error;
    if (!inode_number_out) return RINFS_ERR_INVAL;
    *inode_number_out = 0u;
    error = rinfs_restore_transaction_operation_begin(
        transaction, 0, &operation, &internal);
    if (error != RINFS_OK) return error;
    error = rinfs_restore_transaction_load_inode_core(
        internal, entry_index, inode_number_out);
    release_error = rinfs_restore_transaction_operation_end(&operation, 0);
    return release_error == RINFS_OK ? error : release_error;
}

static int rinfs_restore_transaction_set_root_metadata_core(
    RinFS_RestoreTransactionInternal* internal, uint16_t mode,
    uint16_t persistent_flags, uint32_t uid, uint32_t gid,
    const RinFS_InodeTimes* times, int64_t change_time_seconds) {
    int error = rinfs_restore_transaction_validate_internal(internal);
    if (error != RINFS_OK) return error;
    if (!rinfs_restore_mode_valid(mode) ||
        ((mode >> 12u) & 0x0fu) != RINFS_FT_DIR ||
        (persistent_flags &
         (uint16_t)~RINFS_RESTORE_PERSISTENT_FLAGS) != 0u ||
        !rinfs_restore_times_valid(times) || change_time_seconds < 0)
        return RINFS_ERR_INVAL;
    internal->record.root_mode = mode;
    internal->record.root_flags = persistent_flags;
    internal->record.root_uid = uid;
    internal->record.root_gid = gid;
    internal->record.root_times = *times;
    internal->record.root_change_time_seconds = change_time_seconds;
    internal->record.root_metadata_valid = 1u;
    return rinfs_restore_record_store(internal->mount, &internal->record);
}

int rinfs_restore_transaction_set_root_metadata(
    RinFS_RestoreTransactionV1* transaction, uint16_t mode,
    uint16_t persistent_flags, uint32_t uid, uint32_t gid,
    const RinFS_InodeTimes* times, int64_t change_time_seconds) {
    RinFS_RestoreTransactionOperation operation;
    RinFS_RestoreTransactionInternal* internal = NULL;
    int error = rinfs_restore_transaction_operation_begin(
        transaction, 0, &operation, &internal);
    int release_error;
    if (error != RINFS_OK) return error;
    error = rinfs_restore_transaction_set_root_metadata_core(
        internal, mode, persistent_flags, uid, gid, times,
        change_time_seconds);
    release_error = rinfs_restore_transaction_operation_end(&operation, 0);
    return release_error == RINFS_OK ? error : release_error;
}

static int rinfs_restore_transaction_set_inode_metadata_core(
    RinFS_RestoreTransactionInternal* internal, uint64_t inode_number,
    uint16_t mode, uint16_t persistent_flags, uint32_t uid, uint32_t gid,
    const RinFS_InodeTimes* times, int64_t change_time_seconds) {
    RinFS_RestoreMetadataRecord metadata;
    RinFS_Inode inode;
    RinFS_File file;
    uint64_t offset;
    int64_t written;
    int error;
    error = rinfs_restore_transaction_validate_internal(internal);
    if (error != RINFS_OK) return error;
    if (inode_number == 0u ||
        inode_number > internal->mount->sb.s_inode_count ||
        !rinfs_restore_mode_valid(mode) ||
        (persistent_flags &
         (uint16_t)~RINFS_RESTORE_PERSISTENT_FLAGS) != 0u ||
        !rinfs_restore_times_valid(times) || change_time_seconds < 0 ||
        internal->record.metadata_entries >=
            internal->mount->sb.s_inode_count ||
        internal->record.metadata_entries >
            UINT64_MAX / sizeof(metadata))
        return RINFS_ERR_INVAL;
    error = rinfs_inode_read(internal->mount, inode_number, &inode);
    if (error != RINFS_OK) return error;
    if (inode.i_generation == 0u ||
        ((inode.i_mode >> 12u) & 0x0fu) != ((mode >> 12u) & 0x0fu))
        return RINFS_ERR_STALE;
    rinfs_memset(&metadata, 0, sizeof(metadata));
    metadata.magic = RINFS_RESTORE_TX_MAGIC;
    metadata.inode_number = inode_number;
    metadata.inode_generation = inode.i_generation;
    metadata.mode = mode;
    metadata.persistent_flags = persistent_flags;
    metadata.uid = uid;
    metadata.gid = gid;
    metadata.times = *times;
    metadata.change_time_seconds = change_time_seconds;
    metadata.checksum = rinfs_restore_checksum(&metadata, sizeof(metadata),
        (uint32_t)__builtin_offsetof(RinFS_RestoreMetadataRecord, checksum));
    offset = internal->record.metadata_entries * sizeof(metadata);
    error = rinfs_open_ino(internal->mount,
        internal->record.metadata_inode,
        RIN_VFS_OPEN_READ | RIN_VFS_OPEN_WRITE, &file);
    if (error != RINFS_OK) return error;
    written = rinfs_pwrite(&file, &metadata, sizeof(metadata), offset);
    if (written != (int64_t)sizeof(metadata)) {
        error = written < 0 ? (int)written : RINFS_ERR_IO;
        {
            int close_error = rinfs_close(&file);
            return close_error == RINFS_OK ? error : close_error;
        }
    }
    error = rinfs_restore_file_sync_close(&file);
    if (error != RINFS_OK) return error;
    ++internal->record.metadata_entries;
    return rinfs_restore_record_store(internal->mount, &internal->record);
}

int rinfs_restore_transaction_set_inode_metadata(
    RinFS_RestoreTransactionV1* transaction, uint64_t inode_number,
    uint16_t mode, uint16_t persistent_flags, uint32_t uid, uint32_t gid,
    const RinFS_InodeTimes* times, int64_t change_time_seconds) {
    RinFS_RestoreTransactionOperation operation;
    RinFS_RestoreTransactionInternal* internal = NULL;
    int error = rinfs_restore_transaction_operation_begin(
        transaction, 0, &operation, &internal);
    int release_error;
    if (error != RINFS_OK) return error;
    error = rinfs_restore_transaction_set_inode_metadata_core(
        internal, inode_number, mode, persistent_flags, uid, gid, times,
        change_time_seconds);
    release_error = rinfs_restore_transaction_operation_end(&operation, 0);
    return release_error == RINFS_OK ? error : release_error;
}

int rinfs_restore_transaction_set_directory_metadata(
    RinFS_RestoreTransactionV1* transaction, uint64_t inode_number,
    uint16_t mode, uint16_t persistent_flags, uint32_t uid, uint32_t gid,
    const RinFS_InodeTimes* times, int64_t change_time_seconds) {
    if (((mode >> 12u) & 0x0fu) != RINFS_FT_DIR)
        return RINFS_ERR_INVAL;
    return rinfs_restore_transaction_set_inode_metadata(
        transaction, inode_number, mode, persistent_flags, uid, gid,
        times, change_time_seconds);
}

int rinfs_createat_owned(RinFS_Mount* mount, uint64_t parent_ino,
                         const char* name, uint16_t mode, uint32_t uid,
                         uint32_t gid, uint64_t* created_ino) {
    RinFS_MountOperationScope operation = {0};
    int error;
    if (created_ino) *created_ino = 0u;
    if (!mount || !mount->mounted || !name || parent_ino == 0u ||
        parent_ino > mount->sb.s_inode_count)
        return RINFS_ERR_INVAL;
    error = rinfs_mount_operation_scope_begin(mount, &operation);
    if (error != RINFS_OK) return error;
    error = rinfs_createat_owned_unscoped(
        mount, parent_ino, name, mode, uid, gid, created_ino);
    return rinfs_mount_operation_scope_finish(&operation, error);
}

